insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a2-woh-01','A2','wohnen','a2-wohnen-1','phrase','Wir suchen eine Dreizimmerwohnung mit Balkon.','Мы ищем трёхкомнатную квартиру с балконом.','Ми шукаємо трикімнатну квартиру з балконом.','Wir suchen eine ___ mit Balkon.',null,null,null,null,null,array[]::text[],102000),
('a2-woh-02','A2','wohnen','a2-wohnen-1','phrase','Wie hoch ist die Kaltmiete?','Какая аренда без коммунальных?','Яка оренда без комунальних?','Wie hoch ist die ___?',null,null,null,null,null,array[]::text[],102001),
('a2-woh-03','A2','wohnen','a2-wohnen-1','phrase','Die Nebenkosten sind nicht inklusive.','Коммунальные расходы не включены.','Комунальні витрати не включені.','Die ___ sind nicht inklusive.',null,null,null,null,null,array[]::text[],102002),
('a2-woh-04','A2','wohnen','a2-wohnen-1','phrase','Wann kann ich die Wohnung besichtigen?','Когда я могу посмотреть квартиру?','Коли я можу подивитися квартиру?','Wann kann ich die Wohnung ___?',null,null,null,null,null,array['modal_verbs']::text[],102003),
('a2-woh-05','A2','wohnen','a2-wohnen-1','phrase','Die Kaution beträgt drei Monatsmieten.','Залог — три месячные платы.','Застава — три місячні оплати.','Die ___ beträgt drei Monatsmieten.',null,null,null,null,null,array[]::text[],102004),
('a2-woh-06','A2','wohnen','a2-wohnen-1','phrase','Im Bad tropft der Wasserhahn.','В ванной капает кран.','У ванній капає кран.','Im Bad ___ der Wasserhahn.',null,null,null,null,null,array['word_order_v2']::text[],102005),
('a2-woh-07','A2','wohnen','a2-wohnen-1','phrase','Der Hausmeister kommt morgen vorbei.','Завхоз зайдёт завтра.','Завгосп зайде завтра.','Der Hausmeister kommt morgen ___.',null,null,null,null,null,array[]::text[],102006),
('a2-woh-08','A2','wohnen','a2-wohnen-1','phrase','Bitte trennen Sie den Müll.','Пожалуйста, сортируйте мусор.','Будь ласка, сортуйте сміття.','Bitte ___ Sie den Müll.',null,null,null,null,null,array[]::text[],102007),
('a2-woh-09','A2','wohnen','a2-wohnen-1','phrase','Der gelbe Sack ist für Verpackungen.','Жёлтый мешок — для упаковки.','Жовтий мішок — для упаковок.','Der gelbe Sack ist für ___.',null,null,null,null,null,array[]::text[],102008),
('a2-woh-10','A2','wohnen','a2-wohnen-1','phrase','Ab 22 Uhr ist Nachtruhe.','С 22 часов — ночная тишина.','З 22 години — нічна тиша.','Ab 22 Uhr ist ___.',null,null,null,null,null,array[]::text[],102009),
('a2-woh-11','A2','wohnen','a2-wohnen-1','phrase','Wir sind letzten Monat umgezogen.','Мы переехали в прошлом месяце.','Ми переїхали минулого місяця.','Wir sind letzten Monat ___.',null,null,null,null,null,array['tense_perfekt']::text[],102010),
('a2-woh-12','A2','wohnen','a2-wohnen-1','phrase','Ich muss mich beim Bürgeramt ummelden.','Мне нужно перерегистрироваться в бюргерамте.','Мені треба перереєструватися в бюргерамті.','Ich muss mich beim Bürgeramt ___.',null,null,null,null,null,array['reflexive','verb_final']::text[],102011),
('a2-woh-13','A2','wohnen','a2-wohnen-1','phrase','Die Heizung funktioniert nicht richtig.','Отопление работает неправильно.','Опалення працює неправильно.','Die Heizung ___ nicht richtig.',null,null,null,null,null,array[]::text[],102012),
('a2-woh-14','A2','wohnen','a2-wohnen-1','phrase','Darf ich hier mein Fahrrad abstellen?','Можно мне здесь поставить велосипед?','Можна мені тут поставити велосипед?','Darf ich hier mein Fahrrad ___?',null,null,null,null,null,array['modal_verbs']::text[],102013),
('a2-woh-15','A2','wohnen','a2-wohnen-1','phrase','Die Wohnung liegt im dritten Stock, es gibt keinen Aufzug.','Квартира на четвёртом этаже, лифта нет.','Квартира на четвертому поверсі, ліфта немає.','Die Wohnung liegt im dritten Stock, es gibt keinen ___.',null,null,null,null,null,array['negation']::text[],102014),
('a2-woh-16','A2','wohnen','a2-wohnen-1','phrase','Unsere Nachbarn sind sehr hilfsbereit.','Наши соседи очень отзывчивые.','Наші сусіди дуже чуйні.','Unsere Nachbarn sind sehr ___.',null,null,null,null,null,array[]::text[],102015)
