insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a2-arb-01','A2','arbeit','a2-arbeit-1','phrase','Ich arbeite in Teilzeit, 25 Stunden pro Woche.','Я работаю неполный день, 25 часов в неделю.','Я працюю неповний день, 25 годин на тиждень.','Ich arbeite in ___, 25 Stunden pro Woche.',null,null,null,null,null,array[]::text[],103000),
('a2-arb-02','A2','arbeit','a2-arbeit-1','phrase','Ich habe eine Bewerbung geschrieben.','Я написал(а) заявку на работу.','Я написав(ла) заявку на роботу.','Ich habe eine ___ geschrieben.',null,null,null,null,null,array['tense_perfekt']::text[],103001),
('a2-arb-03','A2','arbeit','a2-arbeit-1','phrase','Morgen habe ich ein Vorstellungsgespräch.','Завтра у меня собеседование.','Завтра в мене співбесіда.','Morgen habe ich ein ___.',null,null,null,null,null,array['word_order_v2']::text[],103002),
('a2-arb-04','A2','arbeit','a2-arbeit-1','phrase','Ich arbeite im Schichtdienst.','Я работаю посменно.','Я працюю позмінно.','Ich arbeite im ___.',null,null,null,null,null,array[]::text[],103003),
('a2-arb-05','A2','arbeit','a2-arbeit-1','phrase','Diese Woche habe ich Frühschicht.','На этой неделе у меня утренняя смена.','Цього тижня в мене ранкова зміна.','Diese Woche habe ich ___.',null,null,null,null,null,array['word_order_v2']::text[],103004),
('a2-arb-06','A2','arbeit','a2-arbeit-1','phrase','Ich bin heute krank und kann nicht kommen.','Я сегодня болен(на) и не могу прийти.','Я сьогодні хворий(а) й не можу прийти.','Ich bin heute ___ und kann nicht kommen.',null,null,null,null,null,array[]::text[],103005),
('a2-arb-07','A2','arbeit','a2-arbeit-1','phrase','Ich schicke Ihnen die Krankmeldung.','Я пришлю вам больничный.','Я надішлю вам лікарняний.','Ich schicke Ihnen die ___.',null,null,null,null,null,array['case_dativ']::text[],103006),
('a2-arb-08','A2','arbeit','a2-arbeit-1','phrase','Wie viele Urlaubstage habe ich?','Сколько у меня дней отпуска?','Скільки в мене днів відпустки?','Wie viele ___ habe ich?',null,null,null,null,null,array[]::text[],103007),
('a2-arb-09','A2','arbeit','a2-arbeit-1','phrase','Mein Arbeitsvertrag ist befristet.','Мой трудовой договор срочный.','Мій трудовий договір строковий.','Mein Arbeitsvertrag ist ___.',null,null,null,null,null,array[]::text[],103008),
('a2-arb-10','A2','arbeit','a2-arbeit-1','phrase','Die Probezeit dauert sechs Monate.','Испытательный срок — шесть месяцев.','Випробувальний термін — шість місяців.','Die ___ dauert sechs Monate.',null,null,null,null,null,array[]::text[],103009),
('a2-arb-11','A2','arbeit','a2-arbeit-1','phrase','Können wir die Schicht tauschen?','Можем поменяться сменами?','Можемо помінятися змінами?','Können wir die Schicht ___?',null,null,null,null,null,array['modal_verbs']::text[],103010),
('a2-arb-12','A2','arbeit','a2-arbeit-1','phrase','Ich mache um zwölf Mittagspause.','Я ухожу на обед в двенадцать.','Я йду на обід о дванадцятій.','Ich mache um zwölf ___.',null,null,null,null,null,array[]::text[],103011),
('a2-arb-13','A2','arbeit','a2-arbeit-1','phrase','Mein Kollege hat mir geholfen.','Мой коллега мне помог.','Мій колега мені допоміг.','Mein Kollege hat mir ___.',null,null,null,null,null,array['case_dativ','tense_perfekt']::text[],103012),
('a2-arb-14','A2','arbeit','a2-arbeit-1','phrase','Ich verdiene 14 Euro brutto pro Stunde.','Я зарабатываю 14 евро брутто в час.','Я заробляю 14 євро брутто за годину.','Ich ___ 14 Euro brutto pro Stunde.',null,null,null,null,null,array[]::text[],103013),
('a2-arb-15','A2','arbeit','a2-arbeit-1','phrase','Meine Ausbildung wird hier nicht anerkannt.','Моё образование здесь не признаётся.','Мою освіту тут не визнають.','Meine Ausbildung wird hier nicht ___.',null,null,null,null,null,array[]::text[],103014),
('a2-arb-16','A2','arbeit','a2-arbeit-1','phrase','Ich suche einen Minijob am Wochenende.','Я ищу мини-работу на выходные.','Я шукаю міні-роботу на вихідні.','Ich suche einen ___ am Wochenende.',null,null,null,null,null,array['case_akkusativ']::text[],103015)
