insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a2-ges-01','A2','gesundheit','a2-gesundheit-1','phrase','Ich hätte gern einen Termin bei Dr. Weber.','Я бы хотел(а) записаться к доктору Веберу.','Я б хотів(ла) записатися до лікаря Вебера.','Ich ___ gern einen Termin bei Dr. Weber.',null,null,null,null,null,array['konjunktiv']::text[],104000),
('a2-ges-02','A2','gesundheit','a2-gesundheit-1','phrase','Ich habe seit drei Tagen Fieber.','У меня третий день температура.','У мене третій день температура.','Ich habe ___ drei Tagen Fieber.',null,null,null,null,null,array['case_dativ']::text[],104001),
('a2-ges-03','A2','gesundheit','a2-gesundheit-1','phrase','Mir ist schlecht.','Меня тошнит.','Мене нудить.','Mir ist ___.',null,null,null,null,null,array['case_dativ']::text[],104002),
('a2-ges-04','A2','gesundheit','a2-gesundheit-1','phrase','Mein Hals tut weh.','У меня болит горло.','У мене болить горло.','Mein Hals tut ___.',null,null,null,null,null,array[]::text[],104003),
('a2-ges-05','A2','gesundheit','a2-gesundheit-1','phrase','Ich bin gegen Penizillin allergisch.','У меня аллергия на пенициллин.','У мене алергія на пеніцилін.','Ich bin gegen Penizillin ___.',null,null,null,null,null,array[]::text[],104004),
('a2-ges-06','A2','gesundheit','a2-gesundheit-1','phrase','Sie müssen dreimal täglich eine Tablette nehmen.','Вам нужно принимать одну таблетку три раза в день.','Вам треба приймати одну таблетку тричі на день.','Sie müssen dreimal täglich eine Tablette ___.',null,null,null,null,null,array['modal_verbs','verb_final']::text[],104005),
('a2-ges-07','A2','gesundheit','a2-gesundheit-1','phrase','Ich brauche eine Überweisung zum Facharzt.','Мне нужно направление к специалисту.','Мені потрібне направлення до фахівця.','Ich brauche eine ___ zum Facharzt.',null,null,null,null,null,array[]::text[],104006),
('a2-ges-08','A2','gesundheit','a2-gesundheit-1','phrase','Haben Sie Ihre Versichertenkarte dabei?','У вас с собой страховая карточка?','У вас із собою страхова картка?','Haben Sie Ihre ___ dabei?',null,null,null,null,null,array[]::text[],104007),
('a2-ges-09','A2','gesundheit','a2-gesundheit-1','phrase','Das Rezept bekommen Sie an der Anmeldung.','Рецепт получите на ресепшене.','Рецепт отримаєте на реєстрації.','Das ___ bekommen Sie an der Anmeldung.',null,null,null,null,null,array['word_order_v2']::text[],104008),
('a2-ges-10','A2','gesundheit','a2-gesundheit-1','phrase','Ich muss mich krankschreiben lassen.','Мне нужно взять больничный.','Мені треба взяти лікарняний.','Ich muss mich ___ lassen.',null,null,null,null,null,array[]::text[],104009),
('a2-ges-11','A2','gesundheit','a2-gesundheit-1','phrase','Gute Besserung!','Выздоравливай(те)!','Одужуй(те)!','Gute ___!',null,null,null,null,null,array[]::text[],104010),
('a2-ges-12','A2','gesundheit','a2-gesundheit-1','phrase','Die Apotheke hat heute Notdienst.','Аптека сегодня дежурная.','Аптека сьогодні чергова.','Die Apotheke hat heute ___.',null,null,null,null,null,array[]::text[],104011),
('a2-ges-13','A2','gesundheit','a2-gesundheit-1','phrase','Ich habe mir den Fuß verletzt.','Я повредил(а) ногу.','Я пошкодив(ла) ногу.','Ich habe mir den Fuß ___.',null,null,null,null,null,array['reflexive','tense_perfekt']::text[],104012),
('a2-ges-14','A2','gesundheit','a2-gesundheit-1','phrase','Wie lange muss ich warten?','Сколько мне ждать?','Скільки мені чекати?','Wie lange muss ich ___?',null,null,null,null,null,array[]::text[],104013),
('a2-ges-15','A2','gesundheit','a2-gesundheit-1','phrase','Rufen Sie bei Notfällen die 112 an.','В экстренных случаях звоните 112.','У надзвичайних випадках телефонуйте 112.','Rufen Sie bei ___ die 112 an.',null,null,null,null,null,array['case_dativ']::text[],104014),
('a2-ges-16','A2','gesundheit','a2-gesundheit-1','phrase','Ich gehe einmal im Jahr zur Vorsorge.','Раз в год я хожу на профилактический осмотр.','Раз на рік я ходжу на профогляд.','Ich gehe einmal im Jahr zur ___.',null,null,null,null,null,array['preposition']::text[],104015)
