('a2-amt-11','A2','aemter','a2-aemter-1','phrase','Ich brauche einen Dolmetscher.','Мне нужен переводчик.','Мені потрібен перекладач.','Ich brauche einen ___.',null,null,null,null,null,array['case_akkusativ']::text[],106010),
