('a2-ver-02','A2','verkehr','a2-verkehr-1','phrase','Ich habe ein Deutschlandticket.','У меня Deutschlandticket.','У мене Deutschlandticket.','Ich habe ein ___.',null,null,null,null,null,array[]::text[],107001),
('a2-ver-03','A2','verkehr','a2-verkehr-1','phrase','Muss ich umsteigen?','Мне нужно пересаживаться?','Мені треба пересідати?','Muss ich ___?',null,null,null,null,null,array['modal_verbs']::text[],107002),
('a2-ver-04','A2','verkehr','a2-verkehr-1','phrase','Der Zug hat zehn Minuten Verspätung.','Поезд опаздывает на десять минут.','Потяг запізнюється на десять хвилин.','Der Zug hat zehn Minuten ___.',null,null,null,null,null,array[]::text[],107003),
('a2-ver-05','A2','verkehr','a2-verkehr-1','phrase','Die S-Bahn fällt heute aus.','Электричка сегодня отменена.','Електричка сьогодні скасована.','Die S-Bahn ___ heute aus.',null,null,null,null,null,array[]::text[],107004),
