('a2-ver-10','A2','verkehr','a2-verkehr-1','phrase','Ich fahre mit dem Fahrrad zur Arbeit.','Я езжу на работу на велосипеде.','Я їжджу на роботу велосипедом.','Ich fahre ___ dem Fahrrad zur Arbeit.',null,null,null,null,null,array['case_dativ']::text[],107009),
('a2-ver-11','A2','verkehr','a2-verkehr-1','phrase','Hier darf man nicht parken.','Здесь нельзя парковаться.','Тут не можна паркуватися.','Hier darf man nicht ___.',null,null,null,null,null,array['modal_verbs','negation']::text[],107010),
('a2-ver-12','A2','verkehr','a2-verkehr-1','phrase','Ich mache gerade meinen Führerschein.','Я сейчас получаю права.','Я зараз отримую права.','Ich mache gerade meinen ___.',null,null,null,null,null,array[]::text[],107011),
('a2-ver-13','A2','verkehr','a2-verkehr-1','phrase','Wegen einer Baustelle gibt es Stau.','Из-за стройки пробка.','Через будівництво затор.','___ einer Baustelle gibt es Stau.',null,null,null,null,null,array[]::text[],107012),
