insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a2-fre-01','A2','freizeit','a2-freizeit-1','phrase','Hast du am Samstag Zeit?','У тебя есть время в субботу?','У тебе є час у суботу?','Hast du am Samstag ___?',null,null,null,null,null,array[]::text[],108000),
('a2-fre-02','A2','freizeit','a2-freizeit-1','phrase','Wollen wir zusammen ins Kino gehen?','Сходим вместе в кино?','Підемо разом у кіно?','Wollen wir zusammen ___ Kino gehen?',null,null,null,null,null,array['preposition','case_akkusativ']::text[],108001),
('a2-fre-03','A2','freizeit','a2-freizeit-1','phrase','Ich gehe zweimal pro Woche ins Fitnessstudio.','Я хожу в спортзал два раза в неделю.','Я ходжу в спортзал двічі на тиждень.','Ich gehe zweimal pro Woche ins ___.',null,null,null,null,null,array[]::text[],108002),
('a2-fre-04','A2','freizeit','a2-freizeit-1','phrase','Ich interessiere mich für Fotografie.','Я интересуюсь фотографией.','Я цікавлюся фотографією.','Ich interessiere mich ___ Fotografie.',null,null,null,null,null,array['reflexive','preposition']::text[],108003),
('a2-fre-05','A2','freizeit','a2-freizeit-1','phrase','Am Wochenende waren wir am See.','На выходных мы были на озере.','На вихідних ми були на озері.','Am Wochenende ___ wir am See.',null,null,null,null,null,array[]::text[],108004),
('a2-fre-06','A2','freizeit','a2-freizeit-1','phrase','Das Konzert hat mir sehr gut gefallen.','Концерт мне очень понравился.','Концерт мені дуже сподобався.','Das Konzert hat mir sehr gut ___.',null,null,null,null,null,array['case_dativ','tense_perfekt']::text[],108005),
('a2-fre-07','A2','freizeit','a2-freizeit-1','phrase','Ich bin Mitglied in einem Sportverein.','Я состою в спортивном клубе.','Я член спортивного клубу.','Ich bin ___ in einem Sportverein.',null,null,null,null,null,array[]::text[],108006),
('a2-fre-08','A2','freizeit','a2-freizeit-1','phrase','Was machst du gern in deiner Freizeit?','Что ты любишь делать в свободное время?','Що ти любиш робити у вільний час?','Was machst du ___ in deiner Freizeit?',null,null,null,null,null,array[]::text[],108007),
('a2-fre-09','A2','freizeit','a2-freizeit-1','phrase','Lass uns lieber zu Hause bleiben.','Давай лучше останемся дома.','Давай краще залишимося вдома.','Lass uns ___ zu Hause bleiben.',null,null,null,null,null,array[]::text[],108008),
('a2-fre-10','A2','freizeit','a2-freizeit-1','phrase','Wir machen einen Ausflug in die Berge.','Мы едем на экскурсию в горы.','Ми їдемо на екскурсію в гори.','Wir machen einen ___ in die Berge.',null,null,null,null,null,array[]::text[],108009),
('a2-fre-11','A2','freizeit','a2-freizeit-1','phrase','Ich habe keine Lust auf Fernsehen.','Мне не хочется смотреть телевизор.','Мені не хочеться дивитися телевізор.','Ich habe keine ___ auf Fernsehen.',null,null,null,null,null,array['negation']::text[],108010),
('a2-fre-12','A2','freizeit','a2-freizeit-1','phrase','Treffen wir uns um acht vor dem Kino?','Встретимся в восемь у кинотеатра?','Зустрінемося о восьмій біля кінотеатру?','Treffen wir uns um acht ___ dem Kino?',null,null,null,null,null,array['preposition','case_dativ']::text[],108011),
('a2-fre-13','A2','freizeit','a2-freizeit-1','phrase','Im Sommer fahren wir an die Ostsee.','Летом мы едем на Балтийское море.','Улітку ми їдемо на Балтійське море.','Im Sommer fahren wir an die ___.',null,null,null,null,null,array['preposition']::text[],108012),
('a2-fre-14','A2','freizeit','a2-freizeit-1','phrase','Ich lese gerade ein spannendes Buch.','Я сейчас читаю увлекательную книгу.','Я зараз читаю захопливу книжку.','Ich lese gerade ein ___ Buch.',null,null,null,null,null,array['adjective_ending']::text[],108013),
('a2-fre-15','A2','freizeit','a2-freizeit-1','phrase','Hast du Lust, mitzukommen?','Хочешь пойти с нами?','Хочеш піти з нами?','Hast du Lust, ___?',null,null,null,null,null,array[]::text[],108014),
('a2-fre-16','A2','freizeit','a2-freizeit-1','phrase','Leider kann ich heute nicht, vielleicht nächstes Mal.','К сожалению, сегодня не могу, может, в следующий раз.','На жаль, сьогодні не можу, може, наступного разу.','___ kann ich heute nicht, vielleicht nächstes Mal.',null,null,null,null,null,array[]::text[],108015)
