('a2-sch-10','A2','schule','a2-schule-1','phrase','Bald gibt es Zeugnisse.','Скоро табели.','Скоро табелі.','Bald gibt es ___.',null,null,null,null,null,array[]::text[],109009),
('a2-sch-11','A2','schule','a2-schule-1','phrase','In den Ferien fahren wir weg.','На каникулах мы уезжаем.','На канікулах ми їдемо.','In den ___ fahren wir weg.',null,null,null,null,null,array[]::text[],109010),
('a2-sch-12','A2','schule','a2-schule-1','phrase','Mein Sohn möchte eine Ausbildung machen.','Мой сын хочет получить профессию.','Мій син хоче здобути професію.','Mein Sohn möchte eine ___ machen.',null,null,null,null,null,array[]::text[],109011),
('a2-sch-13','A2','schule','a2-schule-1','phrase','Die Klassenfahrt kostet 150 Euro.','Классная поездка стоит 150 евро.','Класна поїздка коштує 150 євро.','Die ___ kostet 150 Euro.',null,null,null,null,null,array[]::text[],109012),
('a2-sch-14','A2','schule','a2-schule-1','phrase','Bitte unterschreiben Sie die Entschuldigung.','Подпишите, пожалуйста, объяснительную.','Підпишіть, будь ласка, пояснювальну.','Bitte unterschreiben Sie die ___.',null,null,null,null,null,array[]::text[],109013),
('a2-sch-15','A2','schule','a2-schule-1','phrase','Die Schule fängt um acht Uhr an.','Школа начинается в восемь.','Школа починається о восьмій.','Die Schule ___ um acht Uhr an.',null,null,null,null,null,array[]::text[],109014),
('a2-sch-16','A2','schule','a2-schule-1','phrase','Mein Kind hat sich in der Pause gestritten.','Мой ребёнок поссорился на перемене.','Моя дитина посварилася на перерві.','Mein Kind hat sich in der Pause ___.',null,null,null,null,null,array['reflexive','tense_perfekt']::text[],109015)
