('a2-med-04','A2','medien','a2-medien-1','phrase','Wie ist dein WLAN-Passwort?','Какой у тебя пароль от Wi-Fi?','Який у тебе пароль від Wi-Fi?','Wie ist dein WLAN-___?',null,null,null,null,null,array[]::text[],110003),
('a2-med-05','A2','medien','a2-medien-1','phrase','Ich lese die Nachrichten auf dem Handy.','Я читаю новости в телефоне.','Я читаю новини в телефоні.','Ich lese die ___ auf dem Handy.',null,null,null,null,null,array[]::text[],110004),
('a2-med-06','A2','medien','a2-medien-1','phrase','Ich habe meinen Handyvertrag gekündigt.','Я расторг(ла) договор на мобильную связь.','Я розірвав(ла) договір на мобільний зв''язок.','Ich habe meinen Handyvertrag ___.',null,null,null,null,null,array['tense_perfekt']::text[],110005),
('a2-med-07','A2','medien','a2-medien-1','phrase','Der Drucker funktioniert nicht.','Принтер не работает.','Принтер не працює.','Der ___ funktioniert nicht.',null,null,null,null,null,array[]::text[],110006),
('a2-med-08','A2','medien','a2-medien-1','phrase','Rufen Sie mich bitte zurück.','Перезвоните мне, пожалуйста.','Передзвоніть мені, будь ласка.','Rufen Sie mich bitte ___.',null,null,null,null,null,array[]::text[],110007),
('a2-med-09','A2','medien','a2-medien-1','phrase','Ich höre morgens Radio.','Утром я слушаю радио.','Зранку я слухаю радіо.','Ich höre morgens ___.',null,null,null,null,null,array['word_order_v2']::text[],110008),
('a2-med-10','A2','medien','a2-medien-1','phrase','Hast du die E-Mail bekommen?','Ты получил(а) e-mail?','Ти отримав(ла) e-mail?','Hast du die E-Mail ___?',null,null,null,null,null,array['tense_perfekt']::text[],110009),
('a2-med-11','A2','medien','a2-medien-1','phrase','Die Verbindung ist schlecht, ich höre dich kaum.','Связь плохая, я тебя едва слышу.','Зв''язок поганий, я тебе ледь чую.','Die ___ ist schlecht, ich höre dich kaum.',null,null,null,null,null,array[]::text[],110010),
('a2-med-12','A2','medien','a2-medien-1','phrase','Ich lade die App herunter.','Я скачиваю приложение.','Я завантажую застосунок.','Ich lade die App ___.',null,null,null,null,null,array[]::text[],110011),
('a2-med-13','A2','medien','a2-medien-1','phrase','Meine Kinder sehen zu viel fern.','Мои дети слишком много смотрят телевизор.','Мої діти забагато дивляться телевізор.','Meine Kinder sehen zu viel ___.',null,null,null,null,null,array[]::text[],110012),
('a2-med-14','A2','medien','a2-medien-1','phrase','Glaub nicht alles, was im Internet steht.','Не верь всему, что пишут в интернете.','Не вір усьому, що пишуть в інтернеті.','Glaub nicht alles, was im Internet ___.',null,null,null,null,null,array['verb_final']::text[],110013),
('a2-med-15','A2','medien','a2-medien-1','phrase','Kannst du das bitte ausdrucken?','Можешь это распечатать?','Можеш це роздрукувати?','Kannst du das bitte ___?',null,null,null,null,null,array[]::text[],110014),
('a2-med-16','A2','medien','a2-medien-1','phrase','Wir machen einen Videoanruf.','Мы созвонимся по видео.','Ми зателефонуємо по відео.','Wir machen einen ___.',null,null,null,null,null,array[]::text[],110015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a2-deutschland-1','A2','deutschland','vocab','Германия и культура (A2)','Німеччина і культура (A2)',111) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a2-deu-01','A2','deutschland','a2-deutschland-1','phrase','In Deutschland gibt es sechzehn Bundesländer.','В Германии шестнадцать федеральных земель.','У Німеччині шістнадцять федеральних земель.','In Deutschland gibt es sechzehn ___.',null,null,null,null,null,array[]::text[],111000),
('a2-deu-02','A2','deutschland','a2-deutschland-1','phrase','Zu Ostern suchen die Kinder Eier.','На Пасху дети ищут яйца.','На Великдень діти шукають яйця.','Zu ___ suchen die Kinder Eier.',null,null,null,null,null,array[]::text[],111001),
('a2-deu-03','A2','deutschland','a2-deutschland-1','phrase','An Silvester gibt es ein Feuerwerk.','В новогоднюю ночь — фейерверк.','У новорічну ніч — феєрверк.','An Silvester gibt es ein ___.',null,null,null,null,null,array[]::text[],111002),
('a2-deu-04','A2','deutschland','a2-deutschland-1','phrase','Am 3. Oktober ist der Tag der Deutschen Einheit.','3 октября — День германского единства.','3 жовтня — День німецької єдності.','Am 3. Oktober ist der Tag der Deutschen ___.',null,null,null,null,null,array[]::text[],111003),
('a2-deu-05','A2','deutschland','a2-deutschland-1','phrase','Die Deutschen sind sehr pünktlich.','Немцы очень пунктуальны.','Німці дуже пунктуальні.','Die Deutschen sind sehr ___.',null,null,null,null,null,array[]::text[],111004),
('a2-deu-06','A2','deutschland','a2-deutschland-1','phrase','Bei uns ist das ganz anders.','У нас это совсем по-другому.','У нас це зовсім інакше.','Bei uns ist das ganz ___.',null,null,null,null,null,array[]::text[],111005),
('a2-deu-07','A2','deutschland','a2-deutschland-1','phrase','Im Dezember gehen wir auf den Weihnachtsmarkt.','В декабре мы идём на рождественскую ярмарку.','У грудні ми йдемо на різдвяний ярмарок.','Im Dezember gehen wir auf den ___.',null,null,null,null,null,array['preposition']::text[],111006),
('a2-deu-08','A2','deutschland','a2-deutschland-1','phrase','Sonntags sind die Geschäfte geschlossen.','По воскресеньям магазины закрыты.','У неділю магазини зачинені.','Sonntags sind die Geschäfte ___.',null,null,null,null,null,array[]::text[],111007),
('a2-deu-09','A2','deutschland','a2-deutschland-1','phrase','Am Rhein gibt es viele Burgen.','На Рейне много замков.','На Рейні багато замків.','Am Rhein gibt es viele ___.',null,null,null,null,null,array[]::text[],111008),
('a2-deu-10','A2','deutschland','a2-deutschland-1','phrase','Der Karneval ist im Rheinland sehr beliebt.','Карнавал в Рейнской области очень популярен.','Карнавал у Рейнській області дуже популярний.','Der Karneval ist im Rheinland sehr ___.',null,null,null,null,null,array[]::text[],111009),
('a2-deu-11','A2','deutschland','a2-deutschland-1','phrase','Hier trennt man den Müll sehr genau.','Здесь очень тщательно сортируют мусор.','Тут дуже ретельно сортують сміття.','Hier ___ man den Müll sehr genau.',null,null,null,null,null,array[]::text[],111010),
('a2-deu-12','A2','deutschland','a2-deutschland-1','phrase','Ich finde die Natur hier wunderschön.','Я считаю, что природа здесь прекрасная.','Я вважаю, що природа тут чудова.','Ich finde die Natur hier ___.',null,null,null,null,null,array[]::text[],111011),
('a2-deu-13','A2','deutschland','a2-deutschland-1','phrase','Am Wochenende machen viele Leute einen Spaziergang.','На выходных многие гуляют.','На вихідних багато людей гуляють.','Am Wochenende machen viele Leute einen ___.',null,null,null,null,null,array[]::text[],111012),
('a2-deu-14','A2','deutschland','a2-deutschland-1','phrase','Berlin ist die Hauptstadt von Deutschland.','Берлин — столица Германии.','Берлін — столиця Німеччини.','Berlin ist die ___ von Deutschland.',null,null,null,null,null,array[]::text[],111013),
('a2-deu-15','A2','deutschland','a2-deutschland-1','phrase','Wie feiert man bei euch Neujahr?','Как у вас празднуют Новый год?','Як у вас святкують Новий рік?','Wie ___ man bei euch Neujahr?',null,null,null,null,null,array[]::text[],111014),
('a2-deu-16','A2','deutschland','a2-deutschland-1','phrase','Ich vermisse manchmal meine Heimat.','Иногда я скучаю по родине.','Іноді я сумую за батьківщиною.','Ich ___ manchmal meine Heimat.',null,null,null,null,null,array[]::text[],111015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-kennenlernen-1','B1','kennenlernen','vocab','Знакомство (B1)','Знайомство (B1)',200) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-ken-01','B1','kennenlernen','b1-kennenlernen-1','phrase','Ich lebe seit drei Jahren hier und fühle mich inzwischen wohl.','Я живу здесь три года и теперь чувствую себя хорошо.','Я живу тут три роки й тепер почуваюся добре.','Ich lebe seit drei Jahren hier und fühle mich ___ wohl.',null,null,null,null,null,array['reflexive']::text[],200000),
('b1-ken-02','B1','kennenlernen','b1-kennenlernen-1','phrase','Als ich nach Deutschland kam, konnte ich kein Wort Deutsch.','Когда я приехал(а) в Германию, я не знал(а) ни слова по-немецки.','Коли я приїхав(ла) до Німеччини, я не знав(ла) жодного слова німецькою.','___ ich nach Deutschland kam, konnte ich kein Wort Deutsch.',null,null,null,null,null,array['verb_final','modal_verbs']::text[],200001),
('b1-ken-03','B1','kennenlernen','b1-kennenlernen-1','phrase','Am Anfang war alles sehr schwierig für mich.','Сначала всё было очень трудно для меня.','Спочатку все було дуже складно для мене.','Am ___ war alles sehr schwierig für mich.',null,null,null,null,null,array[]::text[],200002),
('b1-ken-04','B1','kennenlernen','b1-kennenlernen-1','phrase','Ich habe einen Abschluss als Ingenieurin.','У меня диплом инженера.','У мене диплом інженерки.','Ich habe einen ___ als Ingenieurin.',null,null,null,null,null,array[]::text[],200003),
('b1-ken-05','B1','kennenlernen','b1-kennenlernen-1','phrase','Mein Ziel ist es, wieder in meinem Beruf zu arbeiten.','Моя цель — снова работать по профессии.','Моя мета — знову працювати за фахом.','Mein ___ ist es, wieder in meinem Beruf zu arbeiten.',null,null,null,null,null,array[]::text[],200004),
('b1-ken-06','B1','kennenlernen','b1-kennenlernen-1','phrase','Ich bin froh, dass ich hier so nette Leute kennengelernt habe.','Я рад(а), что познакомился(лась) здесь с такими милыми людьми.','Я радий(а), що познайомився(лася) тут із такими милими людьми.','Ich bin froh, ___ ich hier so nette Leute kennengelernt habe.',null,null,null,null,null,array['verb_final']::text[],200005),
('b1-ken-07','B1','kennenlernen','b1-kennenlernen-1','phrase','Was ich an Deutschland mag, ist die Ordnung.','Что мне нравится в Германии — это порядок.','Що мені подобається в Німеччині — це порядок.','Was ich an Deutschland ___, ist die Ordnung.',null,null,null,null,null,array[]::text[],200006),
('b1-ken-08','B1','kennenlernen','b1-kennenlernen-1','phrase','Obwohl ich viel lerne, fällt mir die Grammatik schwer.','Хотя я много учу, грамматика даётся мне тяжело.','Хоча я багато вчу, граматика дається мені важко.','___ ich viel lerne, fällt mir die Grammatik schwer.',null,null,null,null,null,array['verb_final','word_order_v2']::text[],200007),
('b1-ken-09','B1','kennenlernen','b1-kennenlernen-1','phrase','Ich würde gern meine Sprachkenntnisse verbessern.','Я бы хотел(а) улучшить знание языка.','Я б хотів(ла) покращити знання мови.','Ich ___ gern meine Sprachkenntnisse verbessern.',null,null,null,null,null,array['konjunktiv']::text[],200008),
('b1-ken-10','B1','kennenlernen','b1-kennenlernen-1','phrase','In meiner Heimat habe ich zehn Jahre als Lehrerin gearbeitet.','На родине я десять лет работала учительницей.','На батьківщині я десять років працювала вчителькою.','In meiner ___ habe ich zehn Jahre als Lehrerin gearbeitet.',null,null,null,null,null,array['tense_perfekt']::text[],200009),
('b1-ken-11','B1','kennenlernen','b1-kennenlernen-1','phrase','Ich engagiere mich ehrenamtlich in einem Verein.','Я волонтёрю в одном объединении.','Я волонтерю в одному об''єднанні.','Ich engagiere mich ___ in einem Verein.',null,null,null,null,null,array['reflexive']::text[],200010),
('b1-ken-12','B1','kennenlernen','b1-kennenlernen-1','phrase','Darf ich fragen, was Sie beruflich machen?','Можно спросить, кем вы работаете?','Можна запитати, ким ви працюєте?','Darf ich fragen, was Sie ___ machen?',null,null,null,null,null,array['verb_final']::text[],200011),
('b1-ken-13','B1','kennenlernen','b1-kennenlernen-1','phrase','Es fällt mir leicht, neue Kontakte zu knüpfen.','Мне легко заводить новые знакомства.','Мені легко заводити нові знайомства.','Es fällt mir leicht, neue Kontakte zu ___.',null,null,null,null,null,array[]::text[],200012),
('b1-ken-14','B1','kennenlernen','b1-kennenlernen-1','phrase','Ich habe mich schnell an das Leben hier gewöhnt.','Я быстро привык(ла) к жизни здесь.','Я швидко звик(ла) до життя тут.','Ich habe mich schnell an das Leben hier ___.',null,null,null,null,null,array['reflexive','preposition']::text[],200013),
('b1-ken-15','B1','kennenlernen','b1-kennenlernen-1','phrase','Später möchte ich die deutsche Staatsangehörigkeit beantragen.','Позже я хочу подать на немецкое гражданство.','Пізніше я хочу подати на німецьке громадянство.','Später möchte ich die deutsche ___ beantragen.',null,null,null,null,null,array[]::text[],200014),
('b1-ken-16','B1','kennenlernen','b1-kennenlernen-1','phrase','Wenn ich Zeit habe, treffe ich mich mit Freunden.','Когда у меня есть время, я встречаюсь с друзьями.','Коли маю час, я зустрічаюся з друзями.','___ ich Zeit habe, treffe ich mich mit Freunden.',null,null,null,null,null,array['verb_final','reflexive']::text[],200015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-familie-1','B1','familie','vocab','Семья (B1)','Сім''я (B1)',201) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-fam-01','B1','familie','b1-familie-1','phrase','Wir haben vor fünf Jahren geheiratet.','Мы поженились пять лет назад.','Ми одружилися п''ять років тому.','Wir haben vor fünf Jahren ___.',null,null,null,null,null,array['tense_perfekt']::text[],201000),
('b1-fam-02','B1','familie','b1-familie-1','phrase','Meine Kinder sind zweisprachig aufgewachsen.','Мои дети выросли двуязычными.','Мої діти виросли двомовними.','Meine Kinder sind zweisprachig ___.',null,null,null,null,null,array['tense_perfekt']::text[],201001),
('b1-fam-03','B1','familie','b1-familie-1','phrase','Für mich ist es wichtig, dass die Familie zusammenhält.','Для меня важно, чтобы семья держалась вместе.','Для мене важливо, щоб родина трималася разом.','Für mich ist es wichtig, dass die Familie ___.',null,null,null,null,null,array['verb_final']::text[],201002),
('b1-fam-04','B1','familie','b1-familie-1','phrase','Wir teilen uns die Hausarbeit.','Мы делим домашние дела.','Ми ділимо хатні справи.','Wir ___ uns die Hausarbeit.',null,null,null,null,null,array['reflexive']::text[],201003),
('b1-fam-05','B1','familie','b1-familie-1','phrase','Meine Mutter kommt uns oft besuchen.','Моя мама часто приезжает к нам в гости.','Моя мама часто приїжджає до нас у гості.','Meine Mutter kommt uns oft ___.',null,null,null,null,null,array[]::text[],201004),
('b1-fam-06','B1','familie','b1-familie-1','phrase','Seit der Geburt unseres Sohnes schlafen wir wenig.','С рождения нашего сына мы мало спим.','Відколи народився наш син, ми мало спимо.','Seit der ___ unseres Sohnes schlafen wir wenig.',null,null,null,null,null,array[]::text[],201005),
('b1-fam-07','B1','familie','b1-familie-1','phrase','Meine Tochter ist in der Pubertät und manchmal schwierig.','Моя дочь в подростковом возрасте и иногда трудная.','Моя донька в підлітковому віці й іноді складна.','Meine Tochter ist in der ___ und manchmal schwierig.',null,null,null,null,null,array[]::text[],201006),
('b1-fam-08','B1','familie','b1-familie-1','phrase','Wir nehmen Elternzeit, um mehr Zeit mit dem Baby zu haben.','Мы берём отпуск по уходу, чтобы больше быть с малышом.','Ми беремо відпустку по догляду, щоб більше бути з малям.','Wir nehmen ___, um mehr Zeit mit dem Baby zu haben.',null,null,null,null,null,array[]::text[],201007),
('b1-fam-09','B1','familie','b1-familie-1','phrase','Meine Eltern sind stolz auf mich.','Мои родители гордятся мной.','Мої батьки пишаються мною.','Meine Eltern sind ___ auf mich.',null,null,null,null,null,array['preposition']::text[],201008),
('b1-fam-10','B1','familie','b1-familie-1','phrase','Ich vermisse meine Familie, die noch in der Ukraine ist.','Я скучаю по семье, которая ещё в Украине.','Я сумую за родиною, яка ще в Україні.','Ich vermisse meine Familie, ___ noch in der Ukraine ist.',null,null,null,null,null,array['verb_final']::text[],201009),
('b1-fam-11','B1','familie','b1-familie-1','phrase','Bei uns entscheiden wir alles gemeinsam.','У нас мы всё решаем вместе.','У нас ми все вирішуємо разом.','Bei uns entscheiden wir alles ___.',null,null,null,null,null,array[]::text[],201010),
('b1-fam-12','B1','familie','b1-familie-1','phrase','Mein Bruder hat sich von seiner Frau getrennt.','Мой брат расстался с женой.','Мій брат розлучився з дружиною.','Mein Bruder hat sich von seiner Frau ___.',null,null,null,null,null,array['reflexive','case_dativ']::text[],201011),
('b1-fam-13','B1','familie','b1-familie-1','phrase','Unsere Kinder sollen beide Sprachen sprechen.','Наши дети должны говорить на обоих языках.','Наші діти мають розмовляти обома мовами.','Unsere Kinder ___ beide Sprachen sprechen.',null,null,null,null,null,array['modal_verbs']::text[],201012),
('b1-fam-14','B1','familie','b1-familie-1','phrase','Am Sonntag frühstücken wir immer ausgiebig.','В воскресенье мы всегда долго завтракаем.','У неділю ми завжди довго снідаємо.','Am Sonntag frühstücken wir immer ___.',null,null,null,null,null,array[]::text[],201013),
('b1-fam-15','B1','familie','b1-familie-1','phrase','Die Großeltern helfen uns bei der Kinderbetreuung.','Бабушка с дедушкой помогают нам с детьми.','Бабуся й дідусь допомагають нам із дітьми.','Die Großeltern helfen uns bei der ___.',null,null,null,null,null,array['case_dativ']::text[],201014),
('b1-fam-16','B1','familie','b1-familie-1','phrase','Wir streiten selten, aber wenn, dann laut.','Мы редко ссоримся, но если да — то громко.','Ми рідко сваримося, але якщо так — то гучно.','Wir streiten ___, aber wenn, dann laut.',null,null,null,null,null,array[]::text[],201015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-wohnen-1','B1','wohnen','vocab','Жильё (B1)','Житло (B1)',202) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-woh-01','B1','wohnen','b1-wohnen-1','phrase','Der Mietvertrag ist unbefristet.','Договор аренды бессрочный.','Договір оренди безстроковий.','Der Mietvertrag ist ___.',null,null,null,null,null,array[]::text[],202000),
('b1-woh-02','B1','wohnen','b1-wohnen-1','phrase','Die Kündigungsfrist beträgt drei Monate.','Срок расторжения — три месяца.','Термін розірвання — три місяці.','Die ___ beträgt drei Monate.',null,null,null,null,null,array[]::text[],202001),
('b1-woh-03','B1','wohnen','b1-wohnen-1','phrase','Ich habe die Nebenkostenabrechnung bekommen und muss nachzahlen.','Я получил(а) расчёт коммуналки и должен(на) доплатить.','Я отримав(ла) розрахунок комуналки й маю доплатити.','Ich habe die Nebenkostenabrechnung bekommen und muss ___.',null,null,null,null,null,array['modal_verbs']::text[],202002),
('b1-woh-04','B1','wohnen','b1-wohnen-1','phrase','In der Wohnung ist Schimmel, das ist ein Mangel.','В квартире плесень, это недостаток.','У квартирі пліснява, це недолік.','In der Wohnung ist Schimmel, das ist ein ___.',null,null,null,null,null,array[]::text[],202003),
('b1-woh-05','B1','wohnen','b1-wohnen-1','phrase','Der Vermieter muss die Reparatur bezahlen.','Арендодатель обязан оплатить ремонт.','Орендодавець зобов''язаний оплатити ремонт.','Der Vermieter muss die ___ bezahlen.',null,null,null,null,null,array['modal_verbs']::text[],202004),
('b1-woh-06','B1','wohnen','b1-wohnen-1','phrase','Könnten Sie bitte einen Handwerker schicken?','Не могли бы вы прислать мастера?','Чи не могли б ви надіслати майстра?','___ Sie bitte einen Handwerker schicken?',null,null,null,null,null,array['konjunktiv']::text[],202005),
('b1-woh-07','B1','wohnen','b1-wohnen-1','phrase','Unser Nachbar beschwert sich über den Lärm.','Наш сосед жалуется на шум.','Наш сусід скаржиться на шум.','Unser Nachbar ___ sich über den Lärm.',null,null,null,null,null,array['reflexive','preposition']::text[],202006),
('b1-woh-08','B1','wohnen','b1-wohnen-1','phrase','Wir suchen eine Wohnung, die in der Nähe einer Schule liegt.','Мы ищем квартиру, которая находится рядом со школой.','Ми шукаємо квартиру, яка розташована біля школи.','Wir suchen eine Wohnung, die in der Nähe einer Schule ___.',null,null,null,null,null,array['verb_final']::text[],202007),
('b1-woh-09','B1','wohnen','b1-wohnen-1','phrase','Für die Wohnung brauche ich einen Wohnberechtigungsschein.','Для квартиры мне нужен WBS (право на соцжильё).','Для квартири мені потрібен WBS (право на соцжитло).','Für die Wohnung brauche ich einen ___.',null,null,null,null,null,array[]::text[],202008),
('b1-woh-10','B1','wohnen','b1-wohnen-1','phrase','Die Miete wird am Anfang des Monats überwiesen.','Аренда переводится в начале месяца.','Оренда переказується на початку місяця.','Die Miete wird am Anfang des Monats ___.',null,null,null,null,null,array['tense_perfekt']::text[],202009),
('b1-woh-11','B1','wohnen','b1-wohnen-1','phrase','Die Wohnung wurde letztes Jahr renoviert.','Квартиру отремонтировали в прошлом году.','Квартиру відремонтували минулого року.','Die Wohnung wurde letztes Jahr ___.',null,null,null,null,null,array[]::text[],202010),
('b1-woh-12','B1','wohnen','b1-wohnen-1','phrase','Haustiere sind nur nach Absprache erlaubt.','Домашние животные — только по договорённости.','Домашні тварини — лише за домовленістю.','Haustiere sind nur nach ___ erlaubt.',null,null,null,null,null,array[]::text[],202011),
('b1-woh-13','B1','wohnen','b1-wohnen-1','phrase','Ich hätte gern eine Wohnung mit Einbauküche.','Я бы хотел(а) квартиру со встроенной кухней.','Я б хотів(ла) квартиру з вбудованою кухнею.','Ich hätte gern eine Wohnung mit ___.',null,null,null,null,null,array['konjunktiv']::text[],202012),
('b1-woh-14','B1','wohnen','b1-wohnen-1','phrase','Wir wohnen in einer WG mit zwei Studenten.','Мы живём в квартире с двумя студентами.','Ми живемо у спільній квартирі з двома студентами.','Wir wohnen in einer ___ mit zwei Studenten.',null,null,null,null,null,array[]::text[],202013),
('b1-woh-15','B1','wohnen','b1-wohnen-1','phrase','Wenn die Heizung kaputt ist, rufe ich sofort den Hausmeister an.','Если сломается отопление, я сразу звоню завхозу.','Якщо зламається опалення, я одразу телефоную завгоспу.','Wenn die Heizung kaputt ist, ___ ich sofort den Hausmeister an.',null,null,null,null,null,array['word_order_v2']::text[],202014),
('b1-woh-16','B1','wohnen','b1-wohnen-1','phrase','Beim Auszug muss die Wohnung besenrein sein.','При выезде квартира должна быть убрана.','При виїзді квартира має бути прибрана.','Beim Auszug muss die Wohnung ___ sein.',null,null,null,null,null,array[]::text[],202015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-arbeit-1','B1','arbeit','vocab','Работа (B1)','Робота (B1)',203) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-arb-01','B1','arbeit','b1-arbeit-1','phrase','Hiermit bewerbe ich mich um die Stelle als Pflegekraft.','Настоящим подаю заявку на должность сиделки/медработника.','Цим подаю заявку на посаду доглядальниці/медпрацівника.','Hiermit ___ ich mich um die Stelle als Pflegekraft.',null,null,null,null,null,array['reflexive','preposition']::text[],203000),
('b1-arb-02','B1','arbeit','b1-arbeit-1','phrase','Ich habe Erfahrung im Umgang mit Kunden.','У меня есть опыт работы с клиентами.','У мене є досвід роботи з клієнтами.','Ich habe ___ im Umgang mit Kunden.',null,null,null,null,null,array[]::text[],203001),
('b1-arb-03','B1','arbeit','b1-arbeit-1','phrase','Ich bin zuverlässig und arbeite gern im Team.','Я надёжный(ая) и люблю работать в команде.','Я надійний(а) й люблю працювати в команді.','Ich bin ___ und arbeite gern im Team.',null,null,null,null,null,array[]::text[],203002),
('b1-arb-04','B1','arbeit','b1-arbeit-1','phrase','Welche Aufgaben hätte ich in dieser Position?','Какие задачи у меня были бы на этой должности?','Які завдання я мав(ла) б на цій посаді?','Welche Aufgaben ___ ich in dieser Position?',null,null,null,null,null,array['konjunktiv']::text[],203003),
('b1-arb-05','B1','arbeit','b1-arbeit-1','phrase','Ich möchte mich beruflich weiterbilden.','Я хочу повысить квалификацию.','Я хочу підвищити кваліфікацію.','Ich möchte mich beruflich ___.',null,null,null,null,null,array['reflexive']::text[],203004),
('b1-arb-06','B1','arbeit','b1-arbeit-1','phrase','Mein Chef hat mir eine Gehaltserhöhung versprochen.','Шеф пообещал мне повышение зарплаты.','Шеф пообіцяв мені підвищення зарплати.','Mein Chef hat mir eine ___ versprochen.',null,null,null,null,null,array['tense_perfekt']::text[],203005),
('b1-arb-07','B1','arbeit','b1-arbeit-1','phrase','Überstunden werden bei uns ausbezahlt.','Сверхурочные у нас оплачиваются.','Понаднормові в нас оплачуються.','___ werden bei uns ausbezahlt.',null,null,null,null,null,array[]::text[],203006),
('b1-arb-08','B1','arbeit','b1-arbeit-1','phrase','Ich habe meine Stelle gekündigt, weil ich umziehe.','Я уволился(лась), потому что переезжаю.','Я звільнився(лася), бо переїжджаю.','Ich habe meine Stelle gekündigt, ___ ich umziehe.',null,null,null,null,null,array['verb_final']::text[],203007),
('b1-arb-09','B1','arbeit','b1-arbeit-1','phrase','Die Arbeitszeiten sind flexibel.','Рабочее время гибкое.','Робочий час гнучкий.','Die Arbeitszeiten sind ___.',null,null,null,null,null,array[]::text[],203008),
('b1-arb-10','B1','arbeit','b1-arbeit-1','phrase','Wir haben eine Besprechung um zehn.','У нас совещание в десять.','У нас нарада о десятій.','Wir haben eine ___ um zehn.',null,null,null,null,null,array[]::text[],203009),
('b1-arb-11','B1','arbeit','b1-arbeit-1','phrase','Könnten Sie mir das bitte noch einmal erklären?','Не могли бы вы ещё раз мне это объяснить?','Чи не могли б ви ще раз мені це пояснити?','Könnten Sie mir das bitte noch einmal ___?',null,null,null,null,null,array['konjunktiv']::text[],203010),
('b1-arb-12','B1','arbeit','b1-arbeit-1','phrase','Das Arbeitsklima in unserem Team ist sehr gut.','Атмосфера в нашей команде очень хорошая.','Атмосфера в нашій команді дуже добра.','Das ___ in unserem Team ist sehr gut.',null,null,null,null,null,array[]::text[],203011),
('b1-arb-13','B1','arbeit','b1-arbeit-1','phrase','Ich muss die Unterlagen bis Freitag einreichen.','Мне нужно подать документы до пятницы.','Мені треба подати документи до п''ятниці.','Ich muss die Unterlagen bis Freitag ___.',null,null,null,null,null,array['modal_verbs']::text[],203012),
('b1-arb-14','B1','arbeit','b1-arbeit-1','phrase','Ich bin arbeitslos gemeldet und suche eine neue Stelle.','Я зарегистрирован(а) как безработный(ая) и ищу новое место.','Я зареєстрований(а) як безробітний(а) й шукаю нове місце.','Ich bin ___ gemeldet und suche eine neue Stelle.',null,null,null,null,null,array[]::text[],203013),
('b1-arb-15','B1','arbeit','b1-arbeit-1','phrase','Mein Lebenslauf ist lückenlos.','Моё резюме без пробелов.','Моє резюме без прогалин.','Mein Lebenslauf ist ___.',null,null,null,null,null,array[]::text[],203014),
('b1-arb-16','B1','arbeit','b1-arbeit-1','phrase','Nach der Probezeit wurde ich fest angestellt.','После испытательного срока меня взяли на постоянную работу.','Після випробувального терміну мене взяли на постійну роботу.','Nach der Probezeit wurde ich fest ___.',null,null,null,null,null,array[]::text[],203015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-gesundheit-1','B1','gesundheit','vocab','Врач и здоровье (B1)','Лікар і здоров''я (B1)',204) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-ges-01','B1','gesundheit','b1-gesundheit-1','phrase','Ich leide seit Wochen unter Rückenschmerzen.','Я уже несколько недель страдаю от боли в спине.','Я вже кілька тижнів страждаю від болю в спині.','Ich leide seit Wochen ___ Rückenschmerzen.',null,null,null,null,null,array['preposition']::text[],204000),
('b1-ges-02','B1','gesundheit','b1-gesundheit-1','phrase','Der Arzt hat mir Physiotherapie verschrieben.','Врач прописал мне физиотерапию.','Лікар призначив мені фізіотерапію.','Der Arzt hat mir Physiotherapie ___.',null,null,null,null,null,array['tense_perfekt']::text[],204001),
('b1-ges-03','B1','gesundheit','b1-gesundheit-1','phrase','Ich soll mich mehr bewegen und gesünder essen.','Мне нужно больше двигаться и есть здоровее.','Мені треба більше рухатися й їсти здоровіше.','Ich soll mich mehr ___ und gesünder essen.',null,null,null,null,null,array['reflexive']::text[],204002),
('b1-ges-04','B1','gesundheit','b1-gesundheit-1','phrase','Die Untersuchung hat ergeben, dass alles in Ordnung ist.','Обследование показало, что всё в порядке.','Обстеження показало, що все гаразд.','Die Untersuchung hat ___, dass alles in Ordnung ist.',null,null,null,null,null,array['verb_final']::text[],204003),
('b1-ges-05','B1','gesundheit','b1-gesundheit-1','phrase','Die Krankenkasse übernimmt die Kosten.','Больничная касса берёт на себя расходы.','Лікарняна каса бере на себе витрати.','Die Krankenkasse ___ die Kosten.',null,null,null,null,null,array[]::text[],204004),
('b1-ges-06','B1','gesundheit','b1-gesundheit-1','phrase','Ich muss vor der Blutabnahme nüchtern sein.','Перед анализом крови нужно быть натощак.','Перед аналізом крові треба бути натщесерце.','Ich muss vor der Blutabnahme ___ sein.',null,null,null,null,null,array[]::text[],204005),
('b1-ges-07','B1','gesundheit','b1-gesundheit-1','phrase','Wegen der Grippe war ich eine Woche krankgeschrieben.','Из-за гриппа я неделю был(а) на больничном.','Через грип я тиждень був(ла) на лікарняному.','Wegen der Grippe war ich eine Woche ___.',null,null,null,null,null,array[]::text[],204006),
('b1-ges-08','B1','gesundheit','b1-gesundheit-1','phrase','Haben Sie Nebenwirkungen bemerkt?','Вы заметили побочные эффекты?','Ви помітили побічні дії?','Haben Sie ___ bemerkt?',null,null,null,null,null,array[]::text[],204007),
('b1-ges-09','B1','gesundheit','b1-gesundheit-1','phrase','Ich hätte gern eine zweite Meinung.','Я бы хотел(а) услышать второе мнение.','Я б хотів(ла) почути другу думку.','Ich hätte gern eine zweite ___.',null,null,null,null,null,array['konjunktiv']::text[],204008),
('b1-ges-10','B1','gesundheit','b1-gesundheit-1','phrase','Ich lasse mich gegen Grippe impfen.','Я делаю прививку от гриппа.','Я роблю щеплення від грипу.','Ich lasse mich gegen Grippe ___.',null,null,null,null,null,array['reflexive']::text[],204009),
('b1-ges-11','B1','gesundheit','b1-gesundheit-1','phrase','Nach der Operation muss ich mich schonen.','После операции мне нужно поберечься.','Після операції мені треба берегти себе.','Nach der Operation muss ich mich ___.',null,null,null,null,null,array['reflexive']::text[],204010),
('b1-ges-12','B1','gesundheit','b1-gesundheit-1','phrase','Ich habe ständig Kopfschmerzen, wenn ich am Computer arbeite.','У меня постоянно болит голова, когда я работаю за компьютером.','У мене постійно болить голова, коли я працюю за комп''ютером.','Ich habe ständig Kopfschmerzen, wenn ich am Computer ___.',null,null,null,null,null,array['verb_final']::text[],204011),
('b1-ges-13','B1','gesundheit','b1-gesundheit-1','phrase','Ist das Medikament rezeptpflichtig?','Это лекарство по рецепту?','Ці ліки за рецептом?','Ist das Medikament ___?',null,null,null,null,null,array[]::text[],204012),
('b1-ges-14','B1','gesundheit','b1-gesundheit-1','phrase','Mein Kind hat einen Ausschlag am ganzen Körper.','У моего ребёнка сыпь по всему телу.','У моєї дитини висип по всьому тілу.','Mein Kind hat einen ___ am ganzen Körper.',null,null,null,null,null,array[]::text[],204013),
('b1-ges-15','B1','gesundheit','b1-gesundheit-1','phrase','Bitte füllen Sie den Anamnesebogen aus.','Пожалуйста, заполните анкету о здоровье.','Будь ласка, заповніть анкету про здоров''я.','Bitte füllen Sie den ___ aus.',null,null,null,null,null,array[]::text[],204014),
('b1-ges-16','B1','gesundheit','b1-gesundheit-1','phrase','Stress kann krank machen.','Стресс может вызвать болезнь.','Стрес може спричинити хворобу.','Stress kann ___ machen.',null,null,null,null,null,array['modal_verbs']::text[],204015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-einkaufen-1','B1','einkaufen','vocab','Покупки (B1)','Покупки (B1)',205) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-ein-01','B1','einkaufen','b1-einkaufen-1','phrase','Ich möchte mich über das Produkt beschweren.','Я хочу пожаловаться на товар.','Я хочу поскаржитися на товар.','Ich möchte mich über das Produkt ___.',null,null,null,null,null,array['reflexive','preposition']::text[],205000),
('b1-ein-02','B1','einkaufen','b1-einkaufen-1','phrase','Das Gerät war schon beim Auspacken kaputt.','Прибор был сломан уже при распаковке.','Прилад був зламаний уже при розпакуванні.','Das Gerät war schon beim ___ kaputt.',null,null,null,null,null,array[]::text[],205001),
('b1-ein-03','B1','einkaufen','b1-einkaufen-1','phrase','Kann ich das Geld zurückbekommen?','Можно вернуть деньги?','Можна повернути гроші?','Kann ich das Geld ___?',null,null,null,null,null,array[]::text[],205002),
('b1-ein-04','B1','einkaufen','b1-einkaufen-1','phrase','Auf das Gerät gibt es zwei Jahre Garantie.','На прибор гарантия два года.','На прилад гарантія два роки.','Auf das Gerät gibt es zwei Jahre ___.',null,null,null,null,null,array[]::text[],205003),
('b1-ein-05','B1','einkaufen','b1-einkaufen-1','phrase','Ich habe den Vertrag online abgeschlossen.','Я заключил(а) договор онлайн.','Я уклав(ла) договір онлайн.','Ich habe den Vertrag online ___.',null,null,null,null,null,array['tense_perfekt']::text[],205004),
('b1-ein-06','B1','einkaufen','b1-einkaufen-1','phrase','Innerhalb von 14 Tagen können Sie die Ware zurückschicken.','В течение 14 дней вы можете вернуть товар.','Протягом 14 днів ви можете повернути товар.','___ von 14 Tagen können Sie die Ware zurückschicken.',null,null,null,null,null,array[]::text[],205005),
('b1-ein-07','B1','einkaufen','b1-einkaufen-1','phrase','Die Lieferung verzögert sich um eine Woche.','Доставка задерживается на неделю.','Доставка затримується на тиждень.','Die Lieferung ___ sich um eine Woche.',null,null,null,null,null,array['reflexive']::text[],205006),
('b1-ein-08','B1','einkaufen','b1-einkaufen-1','phrase','Ich vergleiche die Preise, bevor ich etwas kaufe.','Я сравниваю цены, прежде чем что-то купить.','Я порівнюю ціни, перш ніж щось купити.','Ich vergleiche die Preise, ___ ich etwas kaufe.',null,null,null,null,null,array['verb_final']::text[],205007),
('b1-ein-09','B1','einkaufen','b1-einkaufen-1','phrase','Bio-Produkte sind mir wichtig, auch wenn sie teurer sind.','Мне важны био-продукты, даже если они дороже.','Мені важливі біо-продукти, навіть якщо вони дорожчі.','Bio-Produkte sind mir wichtig, auch wenn sie ___ sind.',null,null,null,null,null,array[]::text[],205008),
('b1-ein-10','B1','einkaufen','b1-einkaufen-1','phrase','Ich kaufe lieber auf dem Wochenmarkt ein.','Я предпочитаю покупать на рынке.','Я волію купувати на ринку.','Ich kaufe ___ auf dem Wochenmarkt ein.',null,null,null,null,null,array[]::text[],205009),
('b1-ein-11','B1','einkaufen','b1-einkaufen-1','phrase','Könnten Sie mir das bitte als Geschenk einpacken?','Не могли бы вы упаковать это как подарок?','Чи не могли б ви запакувати це як подарунок?','Könnten Sie mir das bitte als Geschenk ___?',null,null,null,null,null,array['konjunktiv']::text[],205010),
('b1-ein-12','B1','einkaufen','b1-einkaufen-1','phrase','Das Pfand für die Flasche beträgt 25 Cent.','Залог за бутылку — 25 центов.','Застава за пляшку — 25 центів.','Das ___ für die Flasche beträgt 25 Cent.',null,null,null,null,null,array[]::text[],205011),
('b1-ein-13','B1','einkaufen','b1-einkaufen-1','phrase','Ich bezahle in Raten.','Я плачу в рассрочку.','Я плачу в розстрочку.','Ich bezahle in ___.',null,null,null,null,null,array[]::text[],205012),
('b1-ein-14','B1','einkaufen','b1-einkaufen-1','phrase','Das Sonderangebot gilt nur bis Samstag.','Спецпредложение действует только до субботы.','Спецпропозиція діє лише до суботи.','Das Sonderangebot ___ nur bis Samstag.',null,null,null,null,null,array[]::text[],205013),
('b1-ein-15','B1','einkaufen','b1-einkaufen-1','phrase','Den Kassenbon sollten Sie aufheben.','Чек лучше сохранить.','Чек краще зберегти.','Den Kassenbon sollten Sie ___.',null,null,null,null,null,array['konjunktiv']::text[],205014),
('b1-ein-16','B1','einkaufen','b1-einkaufen-1','phrase','Ich hätte gern eine Rechnung mit meinem Namen.','Мне нужен счёт на моё имя.','Мені потрібен рахунок на моє ім''я.','Ich hätte gern eine ___ mit meinem Namen.',null,null,null,null,null,array['konjunktiv']::text[],205015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-aemter-1','B1','aemter','vocab','Ведомства (B1)','Установи (B1)',206) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-amt-01','B1','aemter','b1-aemter-1','phrase','Ich möchte einen Antrag auf Kindergeld stellen.','Я хочу подать заявление на детское пособие.','Я хочу подати заяву на дитячу виплату.','Ich möchte einen ___ auf Kindergeld stellen.',null,null,null,null,null,array['preposition']::text[],206000),
('b1-amt-02','B1','aemter','b1-aemter-1','phrase','Bitte reichen Sie die fehlenden Unterlagen nach.','Пожалуйста, донесите недостающие документы.','Будь ласка, донесіть відсутні документи.','Bitte reichen Sie die ___ Unterlagen nach.',null,null,null,null,null,array['adjective_ending']::text[],206001),
('b1-amt-03','B1','aemter','b1-aemter-1','phrase','Gegen den Bescheid kann man Widerspruch einlegen.','На решение можно подать возражение.','На рішення можна подати заперечення.','Gegen den Bescheid kann man ___ einlegen.',null,null,null,null,null,array[]::text[],206002),
('b1-amt-04','B1','aemter','b1-aemter-1','phrase','Der Antrag wurde bewilligt.','Заявление одобрено.','Заяву схвалено.','Der Antrag wurde ___.',null,null,null,null,null,array[]::text[],206003),
('b1-amt-05','B1','aemter','b1-aemter-1','phrase','Die Bearbeitung dauert etwa vier Wochen.','Рассмотрение длится около четырёх недель.','Розгляд триває близько чотирьох тижнів.','Die ___ dauert etwa vier Wochen.',null,null,null,null,null,array[]::text[],206004),
('b1-amt-06','B1','aemter','b1-aemter-1','phrase','Ich brauche eine beglaubigte Übersetzung meines Diploms.','Мне нужен заверенный перевод диплома.','Мені потрібен засвідчений переклад диплома.','Ich brauche eine ___ Übersetzung meines Diploms.',null,null,null,null,null,array['adjective_ending']::text[],206005),
('b1-amt-07','B1','aemter','b1-aemter-1','phrase','Muss ich persönlich vorbeikommen?','Нужно ли мне прийти лично?','Чи треба мені прийти особисто?','Muss ich ___ vorbeikommen?',null,null,null,null,null,array[]::text[],206006),
('b1-amt-08','B1','aemter','b1-aemter-1','phrase','Ich bin verpflichtet, Änderungen sofort zu melden.','Я обязан(а) сразу сообщать об изменениях.','Я зобов''язаний(а) одразу повідомляти про зміни.','Ich bin ___, Änderungen sofort zu melden.',null,null,null,null,null,array[]::text[],206007),
('b1-amt-09','B1','aemter','b1-aemter-1','phrase','Mein Sachbearbeiter ist im Urlaub.','Мой куратор в отпуске.','Мій куратор у відпустці.','Mein ___ ist im Urlaub.',null,null,null,null,null,array[]::text[],206008),
('b1-amt-10','B1','aemter','b1-aemter-1','phrase','Die Steuererklärung muss bis Ende Juli abgegeben werden.','Налоговую декларацию нужно подать до конца июля.','Податкову декларацію треба подати до кінця липня.','Die ___ muss bis Ende Juli abgegeben werden.',null,null,null,null,null,array[]::text[],206009),
('b1-amt-11','B1','aemter','b1-aemter-1','phrase','Wird mein Abschluss in Deutschland anerkannt?','Признаётся ли мой диплом в Германии?','Чи визнається мій диплом у Німеччині?','Wird mein Abschluss in Deutschland ___?',null,null,null,null,null,array[]::text[],206010),
('b1-amt-12','B1','aemter','b1-aemter-1','phrase','Ich habe eine Frage zu meinem Bescheid.','У меня вопрос по моему решению.','У мене питання щодо мого рішення.','Ich habe eine Frage zu meinem ___.',null,null,null,null,null,array[]::text[],206011),
('b1-amt-13','B1','aemter','b1-aemter-1','phrase','Bitte geben Sie Ihr Aktenzeichen an.','Пожалуйста, укажите номер вашего дела.','Будь ласка, вкажіть номер вашої справи.','Bitte geben Sie Ihr ___ an.',null,null,null,null,null,array[]::text[],206012),
('b1-amt-14','B1','aemter','b1-aemter-1','phrase','Ohne Termin werden Sie leider nicht bedient.','Без записи вас, к сожалению, не обслужат.','Без запису вас, на жаль, не обслужать.','Ohne Termin werden Sie leider nicht ___.',null,null,null,null,null,array['negation']::text[],206013),
('b1-amt-15','B1','aemter','b1-aemter-1','phrase','Das Jobcenter übernimmt die Kosten für den Kurs.','Джобцентр оплачивает курс.','Джобцентр оплачує курс.','Das Jobcenter ___ die Kosten für den Kurs.',null,null,null,null,null,array[]::text[],206014),
('b1-amt-16','B1','aemter','b1-aemter-1','phrase','Ich lege Ihnen eine Kopie meines Ausweises bei.','Прилагаю копию моего удостоверения.','Додаю копію мого посвідчення.','Ich lege Ihnen eine Kopie meines Ausweises ___.',null,null,null,null,null,array[]::text[],206015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-verkehr-1','B1','verkehr','vocab','Транспорт (B1)','Транспорт (B1)',207) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-ver-01','B1','verkehr','b1-verkehr-1','phrase','Wegen eines Streiks fallen heute viele Züge aus.','Из-за забастовки сегодня отменено много поездов.','Через страйк сьогодні скасовано багато потягів.','Wegen eines ___ fallen heute viele Züge aus.',null,null,null,null,null,array[]::text[],207000),
('b1-ver-02','B1','verkehr','b1-verkehr-1','phrase','Ich hätte gern eine Fahrkarte nach Hamburg, hin und zurück.','Мне билет до Гамбурга туда и обратно.','Мені квиток до Гамбурга туди й назад.','Ich hätte gern eine Fahrkarte nach Hamburg, hin und ___.',null,null,null,null,null,array['konjunktiv']::text[],207001),
('b1-ver-03','B1','verkehr','b1-verkehr-1','phrase','Bei mehr als einer Stunde Verspätung bekommt man Geld zurück.','При опоздании больше часа возвращают деньги.','При запізненні понад годину повертають гроші.','Bei mehr als einer Stunde ___ bekommt man Geld zurück.',null,null,null,null,null,array[]::text[],207002),
('b1-ver-04','B1','verkehr','b1-verkehr-1','phrase','Ich bin geblitzt worden.','Меня сфотографировала камера скорости.','Мене сфотографувала камера швидкості.','Ich bin ___ worden.',null,null,null,null,null,array[]::text[],207003),
('b1-ver-05','B1','verkehr','b1-verkehr-1','phrase','Das Auto muss zum TÜV.','Машине нужно пройти техосмотр.','Авто має пройти техогляд.','Das Auto muss zum ___.',null,null,null,null,null,array[]::text[],207004),
('b1-ver-06','B1','verkehr','b1-verkehr-1','phrase','Ich hatte einen kleinen Unfall, zum Glück ist niemand verletzt.','У меня была небольшая авария, к счастью, никто не пострадал.','У мене була невелика аварія, на щастя, ніхто не постраждав.','Ich hatte einen kleinen ___, zum Glück ist niemand verletzt.',null,null,null,null,null,array[]::text[],207005),
('b1-ver-07','B1','verkehr','b1-verkehr-1','phrase','Wenn ich einen Führerschein hätte, würde ich mit dem Auto fahren.','Если бы у меня были права, я бы ездил(а) на машине.','Якби в мене були права, я б їздив(ла) машиною.','Wenn ich einen Führerschein ___, würde ich mit dem Auto fahren.',null,null,null,null,null,array['konjunktiv']::text[],207006),
('b1-ver-08','B1','verkehr','b1-verkehr-1','phrase','Mein ausländischer Führerschein muss umgeschrieben werden.','Мои иностранные права нужно переоформить.','Мої іноземні права треба переоформити.','Mein ausländischer Führerschein muss ___ werden.',null,null,null,null,null,array[]::text[],207007),
('b1-ver-09','B1','verkehr','b1-verkehr-1','phrase','Ich fahre lieber mit dem Fahrrad, weil es umweltfreundlicher ist.','Я лучше езжу на велосипеде, потому что это экологичнее.','Я краще їжджу велосипедом, бо це екологічніше.','Ich fahre lieber mit dem Fahrrad, weil es ___ ist.',null,null,null,null,null,array['verb_final']::text[],207008),
('b1-ver-10','B1','verkehr','b1-verkehr-1','phrase','Ohne gültigen Fahrschein zahlt man 60 Euro.','Без действительного билета платишь 60 евро.','Без дійсного квитка платиш 60 євро.','Ohne ___ Fahrschein zahlt man 60 Euro.',null,null,null,null,null,array['adjective_ending']::text[],207009),
('b1-ver-11','B1','verkehr','b1-verkehr-1','phrase','Die Strecke ist wegen Bauarbeiten gesperrt.','Участок закрыт из-за строительных работ.','Ділянка закрита через будівельні роботи.','Die Strecke ist wegen Bauarbeiten ___.',null,null,null,null,null,array[]::text[],207010),
('b1-ver-12','B1','verkehr','b1-verkehr-1','phrase','Es gibt einen Schienenersatzverkehr mit Bussen.','Вместо поезда ходят автобусы.','Замість потяга курсують автобуси.','Es gibt einen ___ mit Bussen.',null,null,null,null,null,array[]::text[],207011),
('b1-ver-13','B1','verkehr','b1-verkehr-1','phrase','Wie lange brauchen Sie zur Arbeit?','Сколько вы добираетесь до работы?','Скільки ви добираєтеся до роботи?','Wie lange ___ Sie zur Arbeit?',null,null,null,null,null,array[]::text[],207012),
('b1-ver-14','B1','verkehr','b1-verkehr-1','phrase','Ich pendle jeden Tag nach Köln.','Я каждый день езжу на работу в Кёльн.','Я щодня їжджу на роботу до Кельна.','Ich ___ jeden Tag nach Köln.',null,null,null,null,null,array[]::text[],207013),
('b1-ver-15','B1','verkehr','b1-verkehr-1','phrase','Bitte achten Sie auf Ihr Gepäck.','Пожалуйста, следите за своим багажом.','Будь ласка, стежте за своїм багажем.','Bitte ___ Sie auf Ihr Gepäck.',null,null,null,null,null,array['preposition']::text[],207014),
('b1-ver-16','B1','verkehr','b1-verkehr-1','phrase','Ich habe mein Handy im Zug liegen lassen.','Я оставил(а) телефон в поезде.','Я залишив(ла) телефон у потязі.','Ich habe mein Handy im Zug ___ lassen.',null,null,null,null,null,array['tense_perfekt']::text[],207015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-freizeit-1','B1','freizeit','vocab','Свободное время (B1)','Вільний час (B1)',208) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-fre-01','B1','freizeit','b1-freizeit-1','phrase','Seit ich im Chor singe, habe ich viele Freunde gefunden.','С тех пор как пою в хоре, я нашёл(ла) много друзей.','Відколи співаю в хорі, я знайшов(ла) багато друзів.','___ ich im Chor singe, habe ich viele Freunde gefunden.',null,null,null,null,null,array['verb_final']::text[],208000),
('b1-fre-02','B1','freizeit','b1-freizeit-1','phrase','Ich würde gern öfter reisen, wenn ich mehr Geld hätte.','Я бы чаще путешествовал(а), если бы было больше денег.','Я б частіше подорожував(ла), якби мав(ла) більше грошей.','Ich ___ gern öfter reisen, wenn ich mehr Geld hätte.',null,null,null,null,null,array['konjunktiv']::text[],208001),
('b1-fre-03','B1','freizeit','b1-freizeit-1','phrase','Am liebsten verbringe ich Zeit in der Natur.','Больше всего я люблю проводить время на природе.','Найбільше я люблю проводити час на природі.','Am liebsten ___ ich Zeit in der Natur.',null,null,null,null,null,array['word_order_v2']::text[],208002),
('b1-fre-04','B1','freizeit','b1-freizeit-1','phrase','Wir haben uns für einen Tanzkurs angemeldet.','Мы записались на курс танцев.','Ми записалися на курс танців.','Wir haben uns für einen Tanzkurs ___.',null,null,null,null,null,array['reflexive','preposition']::text[],208003),
('b1-fre-05','B1','freizeit','b1-freizeit-1','phrase','Der Ausflug ist wegen des schlechten Wetters ausgefallen.','Экскурсия отменилась из-за плохой погоды.','Екскурсія скасувалася через погану погоду.','Der Ausflug ist wegen des schlechten Wetters ___.',null,null,null,null,null,array['tense_perfekt']::text[],208004),
('b1-fre-06','B1','freizeit','b1-freizeit-1','phrase','Ich treibe regelmäßig Sport, um fit zu bleiben.','Я регулярно занимаюсь спортом, чтобы быть в форме.','Я регулярно займаюся спортом, щоб бути у формі.','Ich treibe ___ Sport, um fit zu bleiben.',null,null,null,null,null,array[]::text[],208005),
('b1-fre-07','B1','freizeit','b1-freizeit-1','phrase','Hast du Lust, am Wochenende wandern zu gehen?','Хочешь пойти в поход на выходных?','Хочеш піти в похід на вихідних?','Hast du Lust, am Wochenende ___ zu gehen?',null,null,null,null,null,array[]::text[],208006),
('b1-fre-08','B1','freizeit','b1-freizeit-1','phrase','Ich freue mich schon auf den Urlaub.','Я уже жду отпуска.','Я вже чекаю на відпустку.','Ich freue mich schon ___ den Urlaub.',null,null,null,null,null,array['reflexive','preposition']::text[],208007),
('b1-fre-09','B1','freizeit','b1-freizeit-1','phrase','Im Urlaub habe ich mich gut erholt.','В отпуске я хорошо отдохнул(а).','У відпустці я добре відпочив(ла).','Im Urlaub habe ich mich gut ___.',null,null,null,null,null,array['reflexive','tense_perfekt']::text[],208008),
('b1-fre-10','B1','freizeit','b1-freizeit-1','phrase','Der Film war spannender, als ich gedacht hatte.','Фильм был интереснее, чем я думал(а).','Фільм був цікавіший, ніж я думав(ла).','Der Film war ___, als ich gedacht hatte.',null,null,null,null,null,array[]::text[],208009),
('b1-fre-11','B1','freizeit','b1-freizeit-1','phrase','Was hältst du davon, wenn wir grillen?','Как ты смотришь на то, чтобы пожарить барбекю?','Як ти дивишся на те, щоб посмажити барбекю?','Was ___ du davon, wenn wir grillen?',null,null,null,null,null,array['verb_final']::text[],208010),
('b1-fre-12','B1','freizeit','b1-freizeit-1','phrase','Ich habe keine Zeit für Hobbys, weil ich viel arbeite.','У меня нет времени на хобби, потому что я много работаю.','У мене немає часу на хобі, бо я багато працюю.','Ich habe keine Zeit für Hobbys, ___ ich viel arbeite.',null,null,null,null,null,array['verb_final']::text[],208011),
('b1-fre-13','B1','freizeit','b1-freizeit-1','phrase','Die Karten für das Konzert waren schnell ausverkauft.','Билеты на концерт быстро раскупили.','Квитки на концерт швидко розкупили.','Die Karten für das Konzert waren schnell ___.',null,null,null,null,null,array[]::text[],208012),
('b1-fre-14','B1','freizeit','b1-freizeit-1','phrase','Wir haben eine Ferienwohnung an der Nordsee gebucht.','Мы забронировали апартаменты на Северном море.','Ми забронювали апартаменти на Північному морі.','Wir haben eine Ferienwohnung an der Nordsee ___.',null,null,null,null,null,array['tense_perfekt']::text[],208013),
('b1-fre-15','B1','freizeit','b1-freizeit-1','phrase','Ehrlich gesagt, finde ich Fußball langweilig.','Честно говоря, по-моему, футбол скучный.','Чесно кажучи, як на мене, футбол нудний.','Ehrlich gesagt, ___ ich Fußball langweilig.',null,null,null,null,null,array['word_order_v2']::text[],208014),
('b1-fre-16','B1','freizeit','b1-freizeit-1','phrase','Lass uns etwas unternehmen!','Давай чем-нибудь займёмся!','Давай чимось займемося!','Lass uns etwas ___!',null,null,null,null,null,array[]::text[],208015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-schule-1','B1','schule','vocab','Школа и дети (B1)','Школа і діти (B1)',209) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-sch-01','B1','schule','b1-schule-1','phrase','Ich mache mir Sorgen, weil mein Sohn schlechte Noten hat.','Я переживаю, потому что у сына плохие оценки.','Я хвилююся, бо в сина погані оцінки.','Ich mache mir ___, weil mein Sohn schlechte Noten hat.',null,null,null,null,null,array['verb_final','reflexive']::text[],209000),
('b1-sch-02','B1','schule','b1-schule-1','phrase','Nach der vierten Klasse wechselt sie aufs Gymnasium.','После четвёртого класса она переходит в гимназию.','Після четвертого класу вона переходить до гімназії.','Nach der vierten Klasse ___ sie aufs Gymnasium.',null,null,null,null,null,array['word_order_v2']::text[],209001),
('b1-sch-03','B1','schule','b1-schule-1','phrase','Die Lehrerin empfiehlt die Realschule.','Учительница рекомендует реальную школу.','Учителька рекомендує реальну школу.','Die Lehrerin ___ die Realschule.',null,null,null,null,null,array[]::text[],209002),
('b1-sch-04','B1','schule','b1-schule-1','phrase','Mein Kind wird in der Schule gemobbt.','Моего ребёнка травят в школе.','Мою дитину цькують у школі.','Mein Kind wird in der Schule ___.',null,null,null,null,null,array[]::text[],209003),
('b1-sch-05','B1','schule','b1-schule-1','phrase','Ich hätte gern einen Gesprächstermin mit der Klassenlehrerin.','Я бы хотел(а) встретиться с классной руководительницей.','Я б хотів(ла) зустрітися з класною керівничкою.','Ich hätte gern einen ___ mit der Klassenlehrerin.',null,null,null,null,null,array['konjunktiv']::text[],209004),
('b1-sch-06','B1','schule','b1-schule-1','phrase','Die Schulpflicht beginnt mit sechs Jahren.','Обязательное обучение начинается с шести лет.','Обов''язкове навчання починається з шести років.','Die ___ beginnt mit sechs Jahren.',null,null,null,null,null,array[]::text[],209005),
('b1-sch-07','B1','schule','b1-schule-1','phrase','Für die Klassenfahrt gibt es Zuschüsse vom Jobcenter.','На поездку класса есть доплаты от джобцентра.','На поїздку класу є доплати від джобцентру.','Für die Klassenfahrt gibt es ___ vom Jobcenter.',null,null,null,null,null,array[]::text[],209006),
('b1-sch-08','B1','schule','b1-schule-1','phrase','Die Kinder lernen in der Schule, Konflikte friedlich zu lösen.','Дети учатся в школе решать конфликты мирно.','Діти вчаться в школі вирішувати конфлікти мирно.','Die Kinder lernen in der Schule, Konflikte ___ zu lösen.',null,null,null,null,null,array[]::text[],209007),
('b1-sch-09','B1','schule','b1-schule-1','phrase','Nach der Schule geht er in die Ganztagsbetreuung.','После уроков он идёт на продлёнку.','Після уроків він іде на продовжений день.','Nach der Schule geht er in die ___.',null,null,null,null,null,array[]::text[],209008),
('b1-sch-10','B1','schule','b1-schule-1','phrase','Meine Tochter möchte nach dem Abitur studieren.','Моя дочь хочет учиться в вузе после абитура.','Моя донька хоче вчитися у виші після абітуру.','Meine Tochter möchte nach dem ___ studieren.',null,null,null,null,null,array[]::text[],209009),
('b1-sch-11','B1','schule','b1-schule-1','phrase','Wir haben für unseren Sohn einen Nachhilfelehrer gefunden.','Мы нашли сыну репетитора.','Ми знайшли синові репетитора.','Wir haben für unseren Sohn einen ___ gefunden.',null,null,null,null,null,array['tense_perfekt']::text[],209010),
('b1-sch-12','B1','schule','b1-schule-1','phrase','Die Eltern sollen sich an den Kosten beteiligen.','Родители должны участвовать в расходах.','Батьки мають брати участь у витратах.','Die Eltern sollen sich an den Kosten ___.',null,null,null,null,null,array['reflexive','preposition']::text[],209011),
('b1-sch-13','B1','schule','b1-schule-1','phrase','In der Kita lernen die Kinder schnell Deutsch.','В детском саду дети быстро учат немецкий.','У дитсадку діти швидко вчать німецьку.','In der Kita ___ die Kinder schnell Deutsch.',null,null,null,null,null,array['word_order_v2']::text[],209012),
('b1-sch-14','B1','schule','b1-schule-1','phrase','Ich bin im Elternbeirat aktiv.','Я активна в родительском совете.','Я активна в батьківській раді.','Ich bin im ___ aktiv.',null,null,null,null,null,array[]::text[],209013),
('b1-sch-15','B1','schule','b1-schule-1','phrase','Die Ausbildung dauert drei Jahre und wird bezahlt.','Обучение длится три года и оплачивается.','Навчання триває три роки й оплачується.','Die Ausbildung dauert drei Jahre und wird ___.',null,null,null,null,null,array[]::text[],209014),
('b1-sch-16','B1','schule','b1-schule-1','phrase','Wenn mein Kind krank ist, bleibe ich zu Hause.','Когда ребёнок болеет, я остаюсь дома.','Коли дитина хворіє, я залишаюся вдома.','Wenn mein Kind krank ist, ___ ich zu Hause.',null,null,null,null,null,array['word_order_v2','verb_final']::text[],209015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-medien-1','B1','medien','vocab','СМИ и связь (B1)','ЗМІ та зв''язок (B1)',210) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-med-01','B1','medien','b1-medien-1','phrase','Ich informiere mich meistens online über Politik.','О политике я обычно узнаю онлайн.','Про політику я зазвичай дізнаюся онлайн.','Ich ___ mich meistens online über Politik.',null,null,null,null,null,array['reflexive','preposition']::text[],210000),
('b1-med-02','B1','medien','b1-medien-1','phrase','Man sollte nicht alles glauben, was in sozialen Netzwerken steht.','Не стоит верить всему, что пишут в соцсетях.','Не варто вірити всьому, що пишуть у соцмережах.','Man ___ nicht alles glauben, was in sozialen Netzwerken steht.',null,null,null,null,null,array['konjunktiv','verb_final']::text[],210001),
('b1-med-03','B1','medien','b1-medien-1','phrase','Meiner Meinung nach verbringen Kinder zu viel Zeit am Handy.','По-моему, дети проводят слишком много времени в телефоне.','На мою думку, діти проводять забагато часу в телефоні.','Meiner ___ nach verbringen Kinder zu viel Zeit am Handy.',null,null,null,null,null,array['word_order_v2']::text[],210002),
('b1-med-04','B1','medien','b1-medien-1','phrase','Ich habe mein Datenvolumen schon aufgebraucht.','Я уже израсходовал(а) мобильный интернет.','Я вже витратив(ла) мобільний інтернет.','Ich habe mein Datenvolumen schon ___.',null,null,null,null,null,array[]::text[],210003),
('b1-med-05','B1','medien','b1-medien-1','phrase','Bitte geben Sie Ihre Daten nicht weiter.','Пожалуйста, не передавайте свои данные.','Будь ласка, не передавайте свої дані.','Bitte geben Sie Ihre Daten nicht ___.',null,null,null,null,null,array['negation']::text[],210004),
('b1-med-06','B1','medien','b1-medien-1','phrase','Die Zeitung berichtet über die Wahlen.','Газета пишет о выборах.','Газета пише про вибори.','Die Zeitung ___ über die Wahlen.',null,null,null,null,null,array['preposition']::text[],210005),
('b1-med-07','B1','medien','b1-medien-1','phrase','Ich habe den Rundfunkbeitrag noch nicht bezahlt.','Я ещё не оплатил(а) радио-телевизионный сбор.','Я ще не сплатив(ла) радіо-телевізійний збір.','Ich habe den ___ noch nicht bezahlt.',null,null,null,null,null,array['negation']::text[],210006),
('b1-med-08','B1','medien','b1-medien-1','phrase','Online-Banking ist praktisch, aber man muss vorsichtig sein.','Онлайн-банкинг удобен, но нужно быть осторожным.','Онлайн-банкінг зручний, але треба бути обережним.','Online-Banking ist praktisch, aber man muss ___ sein.',null,null,null,null,null,array[]::text[],210007),
('b1-med-09','B1','medien','b1-medien-1','phrase','Das ist eine Falschmeldung.','Это фейковая новость.','Це фейкова новина.','Das ist eine ___.',null,null,null,null,null,array[]::text[],210008),
('b1-med-10','B1','medien','b1-medien-1','phrase','Einerseits ist das Internet nützlich, andererseits gefährlich.','С одной стороны интернет полезен, с другой — опасен.','З одного боку інтернет корисний, з іншого — небезпечний.','Einerseits ist das Internet nützlich, ___ gefährlich.',null,null,null,null,null,array[]::text[],210009),
('b1-med-11','B1','medien','b1-medien-1','phrase','Ich habe mich für den Newsletter angemeldet.','Я подписался(лась) на рассылку.','Я підписався(лася) на розсилку.','Ich habe mich für den Newsletter ___.',null,null,null,null,null,array['reflexive','tense_perfekt']::text[],210010),
('b1-med-12','B1','medien','b1-medien-1','phrase','Kannst du mir zeigen, wie man ein Video hochlädt?','Можешь показать, как загрузить видео?','Можеш показати, як завантажити відео?','Kannst du mir zeigen, wie man ein Video ___?',null,null,null,null,null,array['verb_final']::text[],210011),
('b1-med-13','B1','medien','b1-medien-1','phrase','Mein Konto wurde gehackt.','Мой аккаунт взломали.','Мій акаунт зламали.','Mein Konto wurde ___.',null,null,null,null,null,array[]::text[],210012),
('b1-med-14','B1','medien','b1-medien-1','phrase','Ich schaue lieber Filme in der Originalsprache.','Я предпочитаю смотреть фильмы на языке оригинала.','Я волію дивитися фільми мовою оригіналу.','Ich schaue lieber Filme in der ___.',null,null,null,null,null,array[]::text[],210013),
('b1-med-15','B1','medien','b1-medien-1','phrase','Die Werbung im Fernsehen nervt mich.','Реклама по телевизору меня раздражает.','Реклама по телевізору мене дратує.','Die Werbung im Fernsehen ___ mich.',null,null,null,null,null,array[]::text[],210014),
('b1-med-16','B1','medien','b1-medien-1','phrase','Ich lese die Nachrichten auf Deutsch, um mein Deutsch zu verbessern.','Я читаю новости на немецком, чтобы улучшить немецкий.','Я читаю новини німецькою, щоб покращити німецьку.','Ich lese die Nachrichten auf Deutsch, um mein Deutsch zu ___.',null,null,null,null,null,array[]::text[],210015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('b1-deutschland-1','B1','deutschland','vocab','Германия и культура (B1)','Німеччина і культура (B1)',211) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('b1-deu-01','B1','deutschland','b1-deutschland-1','phrase','Deutschland ist eine parlamentarische Demokratie.','Германия — парламентская демократия.','Німеччина — парламентська демократія.','Deutschland ist eine parlamentarische ___.',null,null,null,null,null,array[]::text[],211000),
('b1-deu-02','B1','deutschland','b1-deutschland-1','phrase','Alle Menschen sind vor dem Gesetz gleich.','Все люди равны перед законом.','Усі люди рівні перед законом.','Alle Menschen sind vor dem ___ gleich.',null,null,null,null,null,array[]::text[],211001),
('b1-deu-03','B1','deutschland','b1-deutschland-1','phrase','In Deutschland herrscht Meinungsfreiheit.','В Германии свобода мнений.','У Німеччині свобода думки.','In Deutschland herrscht ___.',null,null,null,null,null,array[]::text[],211002),
('b1-deu-04','B1','deutschland','b1-deutschland-1','phrase','Die Mauer ist 1989 gefallen.','Стена пала в 1989 году.','Стіна впала в 1989 році.','Die Mauer ist 1989 ___.',null,null,null,null,null,array['tense_perfekt']::text[],211003),
('b1-deu-05','B1','deutschland','b1-deutschland-1','phrase','Ab 18 Jahren darf man wählen.','С 18 лет можно голосовать.','З 18 років можна голосувати.','Ab 18 Jahren darf man ___.',null,null,null,null,null,array['modal_verbs']::text[],211004),
('b1-deu-06','B1','deutschland','b1-deutschland-1','phrase','Viele Menschen engagieren sich in Vereinen.','Многие люди участвуют в объединениях.','Багато людей беруть участь в об''єднаннях.','Viele Menschen ___ sich in Vereinen.',null,null,null,null,null,array['reflexive']::text[],211005),
('b1-deu-07','B1','deutschland','b1-deutschland-1','phrase','Mich hat überrascht, wie wichtig hier Mülltrennung ist.','Меня удивило, насколько важна здесь сортировка мусора.','Мене здивувало, наскільки важливе тут сортування сміття.','Mich hat ___, wie wichtig hier Mülltrennung ist.',null,null,null,null,null,array['verb_final']::text[],211006),
('b1-deu-08','B1','deutschland','b1-deutschland-1','phrase','Im Vergleich zu meiner Heimat ist hier alles bürokratischer.','По сравнению с родиной здесь всё бюрократичнее.','Порівняно з батьківщиною тут усе бюрократичніше.','Im ___ zu meiner Heimat ist hier alles bürokratischer.',null,null,null,null,null,array[]::text[],211007),
('b1-deu-09','B1','deutschland','b1-deutschland-1','phrase','Die Deutschen legen viel Wert auf Pünktlichkeit.','Немцы придают большое значение пунктуальности.','Німці надають великого значення пунктуальності.','Die Deutschen legen viel ___ auf Pünktlichkeit.',null,null,null,null,null,array['preposition']::text[],211008),
('b1-deu-10','B1','deutschland','b1-deutschland-1','phrase','Religionsfreiheit ist im Grundgesetz garantiert.','Свобода вероисповедания гарантирована Основным законом.','Свобода віросповідання гарантована Основним законом.','Religionsfreiheit ist im ___ garantiert.',null,null,null,null,null,array[]::text[],211009),
('b1-deu-11','B1','deutschland','b1-deutschland-1','phrase','Männer und Frauen sind gleichberechtigt.','Мужчины и женщины равноправны.','Чоловіки й жінки рівноправні.','Männer und Frauen sind ___.',null,null,null,null,null,array[]::text[],211010),
('b1-deu-12','B1','deutschland','b1-deutschland-1','phrase','Was mir hier gefällt, ist die gute Infrastruktur.','Что мне здесь нравится — хорошая инфраструктура.','Що мені тут подобається — добра інфраструктура.','Was mir hier ___, ist die gute Infrastruktur.',null,null,null,null,null,array['case_dativ']::text[],211011),
('b1-deu-13','B1','deutschland','b1-deutschland-1','phrase','Typisch deutsch finde ich das Kaffeetrinken am Sonntagnachmittag.','Типично немецким я считаю кофе в воскресенье днём.','Типово німецьким я вважаю каву в неділю по обіді.','Typisch deutsch ___ ich das Kaffeetrinken am Sonntagnachmittag.',null,null,null,null,null,array['word_order_v2']::text[],211012),
('b1-deu-14','B1','deutschland','b1-deutschland-1','phrase','Die Integration hat bei mir länger gedauert, als ich dachte.','Интеграция у меня заняла больше времени, чем я думал(а).','Інтеграція в мене тривала довше, ніж я думав(ла).','Die Integration hat bei mir länger ___, als ich dachte.',null,null,null,null,null,array['tense_perfekt']::text[],211013),
('b1-deu-15','B1','deutschland','b1-deutschland-1','phrase','Nordrhein-Westfalen ist das Bundesland mit den meisten Einwohnern.','Северный Рейн-Вестфалия — самая населённая земля.','Північний Рейн-Вестфалія — найнаселеніша земля.','Nordrhein-Westfalen ist das Bundesland mit den meisten ___.',null,null,null,null,null,array['case_dativ']::text[],211014),
('b1-deu-16','B1','deutschland','b1-deutschland-1','phrase','Ich finde es gut, dass es hier so viele Angebote für Migranten gibt.','Я считаю хорошим, что здесь так много программ для мигрантов.','Мені подобається, що тут так багато програм для мігрантів.','Ich finde es gut, dass es hier so viele Angebote für Migranten ___.',null,null,null,null,null,array['verb_final']::text[],211015)
insert into public.lid_questions (id,question,answers,correct,topic,bundesland,image_url,question_ru,question_uk,answers_ru,answers_uk,explanation_ru,explanation_uk) values
(1,'In Deutschland dürfen Menschen offen etwas gegen die Regierung sagen, weil …','["hier Religionsfreiheit gilt.","die Menschen Steuern zahlen.","die Menschen das Wahlrecht haben.","hier Meinungsfreiheit gilt."]'::jsonb,3,'recht',null,null,'В Германии люди могут открыто высказываться против правительства, потому что…','У Німеччині люди можуть відкрито висловлюватися проти уряду, тому що…','["здесь действует свобода вероисповедания.","люди платят налоги.","у людей есть право голоса.","здесь действует свобода мнений."]'::jsonb,'["тут діє свобода віросповідання.","люди сплачують податки.","люди мають право голосу.","тут діє свобода думки."]'::jsonb,'Свобода мнений (Meinungsfreiheit, ст. 5 Основного закона) позволяет открыто критиковать правительство.','Свобода думки (Meinungsfreiheit, ст. 5 Основного закону) дозволяє відкрито критикувати уряд.'),
(2,'In Deutschland können Eltern bis zum 14. Lebensjahr ihres Kindes entscheiden, ob es in der Schule am …','["Geschichtsunterricht teilnimmt.","Religionsunterricht teilnimmt.","Politikunterricht teilnimmt.","Sprachunterricht teilnimmt."]'::jsonb,1,'gesellschaft',null,null,'В Германии родители до 14 лет ребёнка решают, будет ли он посещать в школе…','У Німеччині батьки до 14 років дитини вирішують, чи відвідуватиме вона в школі…','["уроки истории.","уроки религии.","уроки политики.","уроки языка."]'::jsonb,'["уроки історії.","уроки релігії.","уроки політики.","уроки мови."]'::jsonb,'Религия — единственный предмет, от которого можно отказаться; с 14 лет ребёнок решает сам.','Релігія — єдиний предмет, від якого можна відмовитися; з 14 років дитина вирішує сама.'),
(3,'Deutschland ist ein Rechtsstaat. Was ist damit gemeint?','["Alle Einwohner / Einwohnerinnen und der Staat müssen sich an die Gesetze halten.","Der Staat muss sich nicht an die Gesetze halten.","Nur Deutsche müssen die Gesetze befolgen.","Die Gerichte machen die Gesetze."]'::jsonb,0,'recht',null,null,'Германия — правовое государство. Что под этим понимается?','Німеччина — правова держава. Що це означає?','["Все жители и государство должны соблюдать законы.","Государство не обязано соблюдать законы.","Только немцы обязаны соблюдать законы.","Законы создают суды."]'::jsonb,'["Усі мешканці й держава мають дотримуватися законів.","Держава не мусить дотримуватися законів.","Лише німці мають виконувати закони.","Закони ухвалюють суди."]'::jsonb,'Rechtsstaat: законы обязательны для всех, в том числе для самого государства.','Rechtsstaat: закони обов''язкові для всіх, зокрема для самої держави.'),
(4,'Welches Recht gehört zu den Grundrechten in Deutschland?','["Waffenbesitz","Faustrecht","Meinungsfreiheit","Selbstjustiz"]'::jsonb,2,'recht',null,null,'Какое право относится к основным правам в Германии?','Яке право належить до основних прав у Німеччині?','["владение оружием","кулачное право","свобода мнений","самосуд"]'::jsonb,'["володіння зброєю","кулачне право","свобода думки","самосуд"]'::jsonb,'Основные права (Grundrechte) — статьи 1–19 Основного закона; свобода мнений — одно из них.','Основні права (Grundrechte) — статті 1–19 Основного закону; свобода думки — одне з них.'),
(5,'Wahlen in Deutschland sind frei. Was bedeutet das?','["Man darf Geld annehmen, wenn man dafür einen bestimmten Kandidaten / eine bestimmte Kandidatin wählt.","Nur Personen, die noch nie im Gefängnis waren, dürfen wählen.","Der Wähler darf bei der Wahl weder beeinflusst noch zu einer bestimmten Stimmabgabe gezwungen werden und keine Nachteile durch die Wahl haben.","Alle wahlberechtigten Personen müssen wählen."]'::jsonb,2,'demokratie',null,null,'Выборы в Германии свободные. Что это значит?','Вибори в Німеччині вільні. Що це означає?','["Можно брать деньги за то, чтобы проголосовать за определённого кандидата.","Голосовать могут только те, кто никогда не был в тюрьме.","На избирателя нельзя влиять, принуждать его к определённому выбору, и выбор не должен ему вредить.","Все, у кого есть право голоса, обязаны голосовать."]'::jsonb,'["Можна брати гроші за те, щоб проголосувати за певного кандидата.","Голосувати можуть лише ті, хто ніколи не був у в''язниці.","На виборця не можна впливати, примушувати його до певного вибору, і вибір не має йому шкодити.","Усі, хто має право голосу, зобов''язані голосувати."]'::jsonb,'Свободные выборы — без давления и подкупа. Обязанности голосовать в Германии нет.','Вільні вибори — без тиску й підкупу. Обов''язку голосувати в Німеччині немає.'),
(6,'Wie heißt die deutsche Verfassung?','["Volksgesetz","Bundesgesetz","Deutsches Gesetz","Grundgesetz"]'::jsonb,3,'recht',null,null,'Как называется конституция Германии?','Як називається конституція Німеччини?','["народный закон","федеральный закон","немецкий закон","Основной закон"]'::jsonb,'["народний закон","федеральний закон","німецький закон","Основний закон"]'::jsonb,'Конституция Германии — Grundgesetz (Основной закон), действует с 1949 года.','Конституція Німеччини — Grundgesetz (Основний закон), діє з 1949 року.'),
(7,'Welches Recht gehört zu den Grundrechten, die nach der deutschen Verfassung garantiert werden? Das Recht auf …','["Glaubens- und Gewissensfreiheit.","Unterhaltung.","Arbeit.","Wohnung."]'::jsonb,0,'recht',null,null,'Какое право относится к основным правам, гарантированным конституцией Германии? Право на…','Яке право належить до основних прав, гарантованих конституцією Німеччини? Право на…','["свободу вероисповедания и совести.","развлечения.","работу.","жильё."]'::jsonb,'["свободу віросповідання і совісті.","розваги.","роботу.","житло."]'::jsonb,'Glaubens- und Gewissensfreiheit — ст. 4. Права на работу или жильё в Основном законе нет.','Glaubens- und Gewissensfreiheit — ст. 4. Права на роботу чи житло в Основному законі немає.'),
(8,'Was steht nicht im Grundgesetz von Deutschland?','["Die Würde des Menschen ist unantastbar.","Alle sollen gleich viel Geld haben.","Jeder Mensch darf seine Meinung sagen.","Alle sind vor dem Gesetz gleich."]'::jsonb,1,'recht',null,null,'Чего нет в Основном законе Германии?','Чого немає в Основному законі Німеччини?','["Достоинство человека неприкосновенно.","У всех должно быть одинаково денег.","Каждый может высказывать своё мнение.","Все равны перед законом."]'::jsonb,'["Гідність людини недоторканна.","У всіх має бути однаково грошей.","Кожен може висловлювати свою думку.","Усі рівні перед законом."]'::jsonb,'Основной закон гарантирует равенство перед законом, но не одинаковый доход.','Основний закон гарантує рівність перед законом, але не однаковий дохід.'),
(9,'Welches Grundrecht gilt in Deutschland nur für Ausländerinnen/Ausländer? Das Grundrecht auf …','["Schutz der Familie","Menschenwürde","Asyl","Meinungsfreiheit"]'::jsonb,2,'recht',null,null,'Какое основное право в Германии действует только для иностранцев? Право на…','Яке основне право в Німеччині діє лише для іноземців? Право на…','["защиту семьи","человеческое достоинство","убежище","свободу мнений"]'::jsonb,'["захист сім''ї","людську гідність","притулок","свободу думки"]'::jsonb,'Право на убежище (Asyl, ст. 16a) — для политически преследуемых иностранцев.','Право на притулок (Asyl, ст. 16a) — для політично переслідуваних іноземців.'),
(10,'Was ist mit dem deutschen Grundgesetz vereinbar?','["die Prügelstrafe","die Folter","die Todesstrafe","die Geldstrafe"]'::jsonb,3,'recht',null,null,'Что совместимо с Основным законом Германии?','Що сумісне з Основним законом Німеччини?','["телесные наказания","пытки","смертная казнь","денежный штраф"]'::jsonb,'["тілесні покарання","катування","смертна кара","грошовий штраф"]'::jsonb,'Смертная казнь отменена (ст. 102), пытки и телесные наказания запрещены. Штраф — законное наказание.','Смертну кару скасовано (ст. 102), катування й тілесні покарання заборонені. Штраф — законне покарання.'),
(11,'Wie wird die Verfassung der Bundesrepublik Deutschland genannt?','["Grundgesetz","Bundesverfassung","Gesetzbuch","Verfassungsvertrag"]'::jsonb,0,'recht',null,null,'Как называется конституция Федеративной Республики Германия?','Як називається конституція Федеративної Республіки Німеччина?','["Основной закон","Федеральная конституция","Свод законов","Конституционный договор"]'::jsonb,'["Основний закон","Федеральна конституція","Звід законів","Конституційний договір"]'::jsonb,'Grundgesetz — так называется конституция ФРГ.','Grundgesetz — так називається конституція ФРН.'),
(12,'Eine Partei im Deutschen Bundestag will die Pressefreiheit abschaffen. Ist das möglich?','["Ja, wenn mehr als die Hälfte der Abgeordneten im Bundestag dafür sind.","Ja, aber dazu müssen zwei Drittel der Abgeordneten im Bundestag dafür sein.","Nein, denn die Pressefreiheit ist ein Grundrecht. Sie kann nicht abgeschafft werden.","Nein, denn nur der Bundesrat kann die Pressefreiheit abschaffen."]'::jsonb,2,'recht',null,null,'Партия в Бундестаге хочет отменить свободу прессы. Это возможно?','Партія в Бундестазі хоче скасувати свободу преси. Чи це можливо?','["Да, если за это больше половины депутатов Бундестага.","Да, но для этого нужны две трети депутатов Бундестага.","Нет, потому что свобода прессы — основное право. Его нельзя отменить.","Нет, потому что только Бундесрат может отменить свободу прессы."]'::jsonb,'["Так, якщо за це більше половини депутатів Бундестагу.","Так, але для цього потрібні дві третини депутатів Бундестагу.","Ні, бо свобода преси — основне право. Його не можна скасувати.","Ні, бо лише Бундесрат може скасувати свободу преси."]'::jsonb,'Суть основных прав нельзя отменить даже большинством в две трети (ст. 19 и 79).','Суть основних прав не можна скасувати навіть більшістю у дві третини (ст. 19 і 79).'),
(13,'Im Parlament steht der Begriff "Opposition" für …','["die regierenden Parteien.","die Fraktion mit den meisten Abgeordneten.","alle Parteien, die bei der letzten Wahl die 5%-Hürde erreichen konnten.","alle Abgeordneten, die nicht zu der Regierungspartei/den Regierungsparteien gehören."]'::jsonb,3,'demokratie',null,null,'В парламенте понятие «оппозиция» означает…','У парламенті поняття «опозиція» означає…','["правящие партии.","фракцию с наибольшим числом депутатов.","все партии, которые на последних выборах преодолели 5-процентный барьер.","всех депутатов, которые не входят в правящую партию/правящие партии."]'::jsonb,'["правлячі партії.","фракцію з найбільшою кількістю депутатів.","усі партії, що на останніх виборах подолали 5-відсотковий бар''єр.","усіх депутатів, які не належать до правлячої партії/правлячих партій."]'::jsonb,'Оппозиция — те, кто не входит в правительственную коалицию и контролирует её.','Опозиція — ті, хто не входить до урядової коаліції й контролює її.'),
(14,'Meinungsfreiheit in Deutschland heißt, dass ich …','["Passanten auf der Straße beschimpfen darf","meine Meinung im Internet äußern kann","Nazi-, Hamas- oder Islamischer Staat-Symbole öffentlich tragen darf","meine Meinung nur dann äußern darf, solange ich der Regierung nicht widerspreche"]'::jsonb,1,'recht',null,null,'Свобода мнений в Германии означает, что я…','Свобода думки в Німеччині означає, що я…','["могу оскорблять прохожих на улице","могу высказывать своё мнение в интернете","могу публично носить символику нацистов, ХАМАС или «Исламского государства»","могу высказываться, только пока не противоречу правительству"]'::jsonb,'["можу ображати перехожих на вулиці","можу висловлювати свою думку в інтернеті","можу публічно носити символіку нацистів, ХАМАС чи «Ісламської держави»","можу висловлюватися, лише поки не суперечу уряду"]'::jsonb,'Мнение можно высказывать везде, в том числе онлайн. Оскорбления и запрещённые символы наказуемы.','Думку можна висловлювати скрізь, зокрема онлайн. Образи та заборонені символи караються.'),
(15,'Was verbietet das deutsche Grundgesetz?','["Militärdienst","Zwangsarbeit","freie Berufswahl","Arbeit im Ausland"]'::jsonb,1,'recht',null,null,'Что запрещает Основной закон Германии?','Що забороняє Основний закон Німеччини?','["военную службу","принудительный труд","свободный выбор профессии","работу за границей"]'::jsonb,'["військову службу","примусову працю","вільний вибір професії","роботу за кордоном"]'::jsonb,'Принудительный труд запрещён (ст. 12). Выбор профессии свободен.','Примусова праця заборонена (ст. 12). Вибір професії вільний.'),
(16,'Wann ist die Meinungsfreiheit in Deutschland eingeschränkt?','["bei der öffentlichen Verbreitung falscher Behauptungen über einzelne Personen","bei Meinungsäußerungen über die Bundesregierung","bei Diskussionen über Religionen","bei Kritik am Staat"]'::jsonb,0,'recht',null,null,'Когда в Германии ограничена свобода мнений?','Коли в Німеччині обмежена свобода думки?','["при публичном распространении ложных утверждений о конкретных людях","при высказываниях о федеральном правительстве","при дискуссиях о религиях","при критике государства"]'::jsonb,'["у разі публічного поширення неправдивих тверджень про конкретних людей","у разі висловлювань про федеральний уряд","під час дискусій про релігії","у разі критики держави"]'::jsonb,'Клевета (Verleumdung) о конкретном человеке наказуема. Критика государства разрешена.','Наклеп (Verleumdung) про конкретну людину карається. Критика держави дозволена.'),
(17,'Die deutschen Gesetze verbieten …','["Meinungsfreiheit der Einwohner und Einwohnerinnen.","Petitionen der Bürger und Bürgerinnen.","Versammlungsfreiheit der Einwohner und Einwohnerinnen.","Ungleichbehandlung der Bürger und Bürgerinnen durch den Staat."]'::jsonb,3,'recht',null,null,'Немецкие законы запрещают…','Німецькі закони забороняють…','["свободу мнений жителей.","петиции граждан.","свободу собраний жителей.","неравное обращение государства с гражданами."]'::jsonb,'["свободу думки мешканців.","петиції громадян.","свободу зібрань мешканців.","нерівне ставлення держави до громадян."]'::jsonb,'Принцип равенства (ст. 3): государство не может дискриминировать граждан.','Принцип рівності (ст. 3): держава не може дискримінувати громадян.'),
(18,'Welches Grundrecht ist in Artikel 1 des Grundgesetzes der Bundesrepublik Deutschland garantiert?','["die Unantastbarkeit der Menschenwürde","das Recht auf Leben","Religionsfreiheit","Meinungsfreiheit"]'::jsonb,0,'recht',null,null,'Какое основное право гарантирует статья 1 Основного закона ФРГ?','Яке основне право гарантує стаття 1 Основного закону ФРН?','["неприкосновенность человеческого достоинства","право на жизнь","свободу вероисповедания","свободу мнений"]'::jsonb,'["недоторканність людської гідності","право на життя","свободу віросповідання","свободу думки"]'::jsonb,'Ст. 1: «Die Würde des Menschen ist unantastbar» — достоинство человека неприкосновенно.','Ст. 1: «Die Würde des Menschen ist unantastbar» — гідність людини недоторканна.'),
(19,'Was versteht man unter dem Recht der "Freizügigkeit" in Deutschland?','["Man darf sich seinen Wohnort selbst aussuchen.","Man kann seinen Beruf wechseln.","Man darf sich für eine andere Religion entscheiden.","Man darf sich in der Öffentlichkeit nur leicht bekleidet bewegen."]'::jsonb,0,'recht',null,null,'Что понимается под правом на «свободу передвижения» (Freizügigkeit) в Германии?','Що розуміють під правом на «свободу пересування» (Freizügigkeit) у Німеччині?','["Можно самому выбирать место жительства.","Можно сменить профессию.","Можно выбрать другую религию.","Можно ходить по улице в лёгкой одежде."]'::jsonb,'["Можна самостійно обирати місце проживання.","Можна змінити професію.","Можна обрати іншу релігію.","Можна ходити вулицею в легкому одязі."]'::jsonb,'Freizügigkeit (ст. 11) — право жить и переезжать в любое место Германии.','Freizügigkeit (ст. 11) — право жити й переїжджати будь-куди в Німеччині.'),
(20,'Eine Partei in Deutschland verfolgt das Ziel, eine Diktatur zu errichten. Sie ist dann …','["tolerant.","rechtsstaatlich orientiert.","gesetzestreu.","verfassungswidrig."]'::jsonb,3,'demokratie',null,null,'Партия в Германии стремится установить диктатуру. Тогда она…','Партія в Німеччині прагне встановити диктатуру. Тоді вона…','["толерантна.","ориентирована на правовое государство.","законопослушна.","антиконституционна."]'::jsonb,'["толерантна.","орієнтована на правову державу.","законослухняна.","антиконституційна."]'::jsonb,'Цель свергнуть демократию — verfassungswidrig; такую партию может запретить Конституционный суд.','Мета повалити демократію — verfassungswidrig; таку партію може заборонити Конституційний суд.'),
(21,'Welches ist das Wappen der Bundesrepublik Deutschland?','["1","2","3","4"]'::jsonb,0,'demokratie',null,'/lid/q21-{n}.webp','Какой герб у Федеративной Республики Германия?','Який герб у Федеративної Республіки Німеччина?','["1","2","3","4"]'::jsonb,'["1","2","3","4"]'::jsonb,'Герб ФРГ — чёрный орёл (Bundesadler) на золотом щите.','Герб ФРН — чорний орел (Bundesadler) на золотому щиті.'),
(22,'Was für eine Staatsform hat Deutschland?','["Monarchie","Diktatur","Republik","Fürstentum"]'::jsonb,2,'demokratie',null,null,'Какая форма правления в Германии?','Яка форма правління в Німеччині?','["монархия","диктатура","республика","княжество"]'::jsonb,'["монархія","диктатура","республіка","князівство"]'::jsonb,'Германия — федеративная республика (Bundesrepublik).','Німеччина — федеративна республіка (Bundesrepublik).'),
(23,'In Deutschland sind die meisten Erwerbstätigen …','["in kleinen Familienunternehmen beschäftigt.","ehrenamtlich für ein Bundesland tätig.","selbständig mit einer eigenen Firma tätig.","bei einer Firma oder Behörde beschäftigt."]'::jsonb,3,'gesellschaft',null,null,'В Германии большинство работающих…','У Німеччині більшість працюючих…','["работают в маленьких семейных предприятиях.","работают волонтёрами на федеральную землю.","работают самостоятельно в своей фирме.","работают по найму в фирме или учреждении."]'::jsonb,'["працюють у маленьких сімейних підприємствах.","працюють волонтерами на федеральну землю.","працюють самостійно у власній фірмі.","працюють за наймом у фірмі чи установі."]'::jsonb,'Большинство — наёмные работники (Angestellte, Arbeiter, Beamte).','Більшість — наймані працівники (Angestellte, Arbeiter, Beamte).'),
