(305,'Welche Farben hat die Landesflagge von Nordrhein-Westfalen?','["rot-weiß","grün-weiß-rot","schwarz-gold","blau-weiß-rot"]'::jsonb,1,'land','NW',null,'Какие цвета у флага земли Северный Рейн-Вестфалия?','Які кольори має прапор землі Північний Рейн-Вестфалія?','["красный-белый","зелёный-белый-красный","чёрный-золотой","синий-белый-красный"]'::jsonb,'["червоний-білий","зелений-білий-червоний","чорний-золотий","синій-білий-червоний"]'::jsonb,'Флаг NRW: зелёный-белый-красный.','Прапор NRW: зелений-білий-червоний.'),
(306,'Wo können Sie sich in Nordrhein-Westfalen über politische Themen informieren?','["bei den Kirchen","beim Ordnungsamt der Gemeinde","bei der Verbraucherzentrale","bei der Landeszentrale für politische Bildung"]'::jsonb,3,'land','NW',null,'Где в Северном Рейне-Вестфалии можно получить информацию о политике?','Де в Північному Рейні-Вестфалії можна отримати інформацію про політику?','["в церквях","в ведомстве порядка общины","в центре защиты прав потребителей","в Земельном центре политического образования"]'::jsonb,'["у церквах","у відомстві порядку громади","у центрі захисту прав споживачів","у Земельному центрі політичної освіти"]'::jsonb,'Landeszentrale für politische Bildung NRW — бесплатные материалы о политике.','Landeszentrale für politische Bildung NRW — безкоштовні матеріали про політику.'),
(307,'Die Landeshauptstadt von Nordrhein-Westfalen heißt …','["Köln.","Bonn.","Düsseldorf.","Dortmund."]'::jsonb,2,'land','NW',null,'Столица земли Северный Рейн-Вестфалия —…','Столиця землі Північний Рейн-Вестфалія —…','["Кёльн.","Бонн.","Дюссельдорф.","Дортмунд."]'::jsonb,'["Кельн.","Бонн.","Дюссельдорф.","Дортмунд."]'::jsonb,'Столица NRW — Дюссельдорф (крупнейший город — Кёльн).','Столиця NRW — Дюссельдорф (найбільше місто — Кельн).'),
(308,'Welches Bundesland ist Nordrhein-Westfalen?','["1","2","3","4"]'::jsonb,2,'land','NW','/lid/q308.webp','Какая федеральная земля — Северный Рейн-Вестфалия?','Яка федеральна земля — Північний Рейн-Вестфалія?','["1","2","3","4"]'::jsonb,'["1","2","3","4"]'::jsonb,'NRW — на западе Германии, граничит с Нидерландами и Бельгией.','NRW — на заході Німеччини, межує з Нідерландами та Бельгією.'),
(309,'Wie nennt man die Regierungschefin/den Regierungschef in Nordrhein-Westfalen?','["Erster Minister/ Erste Ministerin","Premierminister/ Premierministerin","Bürgermeister/ Bürgermeisterin","Ministerpräsident/ Ministerpräsidentin"]'::jsonb,3,'land','NW',null,'Как называют главу правительства Северного Рейна-Вестфалии?','Як називають голову уряду Північного Рейну-Вестфалії?','["первый министр","премьер-министр","бургомистр","министр-президент"]'::jsonb,'["перший міністр","прем''єр-міністр","бургомістр","міністр-президент"]'::jsonb,'Ministerpräsident NRW — Хендрик Вюст (ХДС).','Ministerpräsident NRW — Гендрік Вюст (ХДС).'),
(310,'Welche Ministerin/ welchen Minister hat Nordrhein-Westfalen nicht?','["Justizminister/ Justizministerin","Außenminister/ Außenministerin","Finanzminister/ Finanzministerin","Innenminister/ Innenministerin"]'::jsonb,1,'land','NW',null,'Какого министра нет в Северном Рейне-Вестфалии?','Якого міністра немає в Північному Рейні-Вестфалії?','["министр юстиции","министр иностранных дел","министр финансов","министр внутренних дел"]'::jsonb,'["міністр юстиції","міністр закордонних справ","міністр фінансів","міністр внутрішніх справ"]'::jsonb,'Внешняя политика — дело федерации, у земель нет МИДа.','Зовнішня політика — справа федерації, у земель немає МЗС.')
insert into public.exam_tasks (id,part,teil,type,level_id,topic_id,instructions,text,audio_url,options,answers,meta,time_limit_sec) values
('h-a-1','hoeren',1,'mc','A2',null,'{"de":"Sie hören vier Ansagen. Zu jeder Ansage gibt es eine Aufgabe. Welche Lösung (a, b oder c) passt am besten?","ru":"Четыре объявления, к каждому одно задание. Какой вариант (a, b, c) подходит лучше всего?","uk":"Чотири оголошення, до кожного одне завдання. Який варіант (a, b, c) підходить найкраще?"}'::jsonb,null,null,'[{"q":"Wann hat die Praxis am Mittwochnachmittag geöffnet?","choices":["Von 15 bis 18 Uhr.","Gar nicht.","Von 8 bis 12 Uhr."],"answer":1,"seg":0,"trap_ru":"Ловушка: 15–18 звучит, но только для вторника и четверга. В среду после обеда закрыто.","trap_uk":"Пастка: 15–18 звучить, але лише для вівторка й четверга. У середу після обіду зачинено."},{"q":"Wie soll Svetlana morgen fahren?","choices":["Mit dem Auto.","Mit der S-Bahn.","Mit dem Taxi."],"answer":1,"seg":1,"trap_ru":"Слово «Auto» звучит первым, но с отрицанием: машина ещё в ремонте.","trap_uk":"Слово «Auto» звучить першим, але із запереченням: авто ще в ремонті."},{"q":"Was ist heute billiger?","choices":["Nur Mäntel und Jacken.","Alles im ersten Stock.","Mäntel, Jacken und Schuhe."],"answer":2,"seg":2,"trap_ru":"Скидка есть и на обувь (zum halben Preis = за полцены) — синоним вместо слова «billiger».","trap_uk":"Знижка є й на взуття (zum halben Preis = за пів ціни) — синонім замість слова «billiger»."},{"q":"Was muss Frau Petrenko tun?","choices":["Einen Termin machen.","Den alten Ausweis mitbringen.","Am Montag anrufen."],"answer":1,"seg":3,"trap_ru":"«Termin» упомянут, но с отрицанием: запись не нужна.","trap_uk":"«Termin» згадано, але із запереченням: запис не потрібен."}]'::jsonb,'[1,1,2,1]'::jsonb,'{"satz":"A","plays":2,"audio":true,"segments":[[{"s":"f","de":"Praxis Dr. Albers, guten Tag. Sie rufen außerhalb unserer Sprechzeiten an. Wir sind montags bis freitags von acht bis zwölf Uhr für Sie da, dienstags und donnerstags auch nachmittags von fünfzehn bis achtzehn Uhr. In dringenden Fällen wählen Sie bitte die 116 117."}],[{"s":"m","de":"Hallo Svetlana, hier ist Jonas. Du, wegen morgen: Ich kann dich leider nicht mit dem Auto abholen, meine Werkstatt hat angerufen, das Auto ist noch nicht fertig. Nimm doch einfach die S-Bahn bis Hauptbahnhof, ich warte dann am Ausgang Nord auf dich. Bis morgen!"}],[{"s":"n","de":"Liebe Kundinnen und Kunden, heute bis achtzehn Uhr: Alle Wintermäntel und Jacken im ersten Stock um dreißig Prozent reduziert. Schuhe gibt es zum halben Preis, aber nur im Erdgeschoss an der Sonderkasse."}],[{"s":"f","de":"Guten Tag, Frau Petrenko, hier ist Gabriele Wolf vom Bürgeramt. Ihr neuer Personalausweis ist da. Sie können ihn ab Montag abholen. Bitte bringen Sie den alten Ausweis mit. Einen Termin brauchen Sie dafür nicht."}]]}'::jsonb,null),
('h-a-2','hoeren',2,'mc','A2','medien','{"de":"Sie hören fünf Ansagen aus dem Radio. Zu jeder Ansage gibt es eine Aufgabe. Welche Lösung (a, b oder c) passt am besten?","ru":"Пять объявлений по радио. Какой вариант подходит лучше всего?","uk":"П''ять оголошень по радіо. Який варіант підходить найкраще?"}'::jsonb,null,null,'[{"q":"Wie wird das Wetter morgen Nachmittag?","choices":["Es regnet.","Es wird besser.","Es wird kälter."],"answer":1,"seg":0,"trap_ru":"Дождь только утром. «Freundlicher» = погода улучшается — синоним к «besser».","trap_uk":"Дощ лише зранку. «Freundlicher» = погода покращується — синонім до «besser»."},{"q":"Was sollen Autofahrer tun?","choices":["Eine andere Autobahn nehmen.","Zwanzig Minuten warten.","In Bochum-West abfahren."],"answer":0,"seg":1,"trap_ru":"«Umleitung über die A43» = ехать по другой автостраде. 20 минут — это потеря времени, а не совет.","trap_uk":"«Umleitung über die A43» = їхати іншою автострадою. 20 хвилин — це втрата часу, а не порада."},{"q":"Was gibt es am Samstag im Museum?","choices":["Eintritt frei für alle.","Eine Führung in mehreren Sprachen.","Ein Programm nur für Kinder."],"answer":1,"seg":2,"trap_ru":"Бесплатно только детям до 12, взрослые платят половину. Экскурсия на украинском и русском — «в нескольких языках».","trap_uk":"Безкоштовно лише дітям до 12, дорослі платять половину. Екскурсія українською й російською — «кількома мовами»."},{"q":"Auf der Ausbildungsmesse kann man","choices":["sofort mit Firmen sprechen.","einen Lebenslauf schreiben lassen.","nur Informationen bekommen."],"answer":0,"seg":3,"trap_ru":"Лебенслауф нужно принести самому, а не заказать. «Direkt Gespräche» = сразу поговорить.","trap_uk":"Резюме треба принести самому, а не замовити. «Direkt Gespräche» = одразу поговорити."},{"q":"Was passiert am Dienstag?","choices":["Das Wasser kostet mehr.","In einem Stadtteil gibt es zeitweise kein Wasser.","Die Stadtwerke sind geschlossen."],"answer":1,"seg":4,"trap_ru":"«Nordstadt» = один район, «zwischen neun und dreizehn Uhr» = временно.","trap_uk":"«Nordstadt» = один район, «zwischen neun und dreizehn Uhr» = тимчасово."}]'::jsonb,'[1,0,1,0,1]'::jsonb,'{"satz":"A","plays":1,"audio":true,"segments":[[{"s":"n","de":"Und jetzt das Wetter für morgen: Am Vormittag noch Regen, ab Mittag wird es freundlicher und im Westen kommt sogar die Sonne heraus. Die Temperaturen steigen auf vierzehn Grad."}],[{"s":"m","de":"Achtung, Autofahrer auf der A40 Richtung Essen: Zwischen Bochum-Stahlhausen und Bochum-West ist ein Fahrstreifen wegen Bauarbeiten gesperrt. Sie verlieren dort etwa zwanzig Minuten. Wir empfehlen, die Umleitung über die A43 zu nehmen."}],[{"s":"n","de":"Am Samstag ist wieder Familientag im Stadtmuseum. Kinder unter zwölf Jahren haben freien Eintritt, Erwachsene zahlen nur die Hälfte. Um elf Uhr gibt es eine Führung auf Ukrainisch und Russisch."}],[{"s":"m","de":"Sie suchen einen Ausbildungsplatz? Dann kommen Sie am Donnerstag zur Ausbildungsmesse in die Westfalenhalle. Über hundert Firmen stellen sich vor. Bringen Sie Ihren Lebenslauf mit – viele Firmen führen direkt Gespräche."}],[{"s":"n","de":"Eine Information der Stadtwerke: Wegen Arbeiten an den Leitungen gibt es am Dienstag zwischen neun und dreizehn Uhr in der Nordstadt kein Wasser. Bitte füllen Sie vorher Wasser ab."}]]}'::jsonb,null),
('h-a-3','hoeren',3,'rf-mc','B1',null,'{"de":"Sie hören vier Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben: richtig oder falsch und a, b oder c.","ru":"Четыре разговора, к каждому два задания: верно/неверно и a, b, c.","uk":"Чотири розмови, до кожної два завдання: правильно/неправильно та a, b, c."}'::jsonb,null,null,'[{"q":"Die Frau zieht aus.","choices":["richtig","falsch"],"answer":0,"seg":0,"trap_ru":"«Ich ziehe am Wochenende aus» — прямо сказано.","trap_uk":"«Ich ziehe am Wochenende aus» — прямо сказано."},{"q":"Wer nimmt die Schlüssel an?","choices":["Herr Novak.","Die Frau von Herrn Novak.","Der Hausmeister."],"answer":1,"seg":0,"trap_ru":"Херр Новак отказывается (будет в Кёльне), поможет его жена.","trap_uk":"Пан Новак відмовляється (буде в Кельні), допоможе його дружина."},{"q":"Olena ist mit ihren Kollegen zufrieden.","choices":["richtig","falsch"],"answer":0,"seg":1,"trap_ru":"«Total nett» = очень милые. «Anstrengend» относится к сменам, не к коллегам.","trap_uk":"«Total nett» = дуже милі. «Anstrengend» стосується змін, а не колег."},{"q":"Was sagt der Chef?","choices":["Olena muss um sechs anfangen.","Olena kann später vielleicht andere Schichten arbeiten.","Olena bekommt ab Januar mehr Geld."],"answer":1,"seg":1,"trap_ru":"Шесть утра — это слова Олены, не шефа. Шеф говорит про позднюю смену.","trap_uk":"Шоста ранку — це слова Олени, не шефа. Шеф говорить про пізню зміну."},{"q":"Der Bus 12 fährt zum Klinikum.","choices":["richtig","falsch"],"answer":1,"seg":2,"trap_ru":"12-й идёт к вокзалу, к клинике — 7-й.","trap_uk":"12-й їде до вокзалу, до клініки — 7-й."},{"q":"Die Frau soll","choices":["hier auf die 7 warten.","zu einer anderen Haltestelle gehen.","zum Bahnhof fahren."],"answer":1,"seg":2,"trap_ru":"7-й сегодня отсюда не ходит — нужно идти на Marktplatz.","trap_uk":"7-й сьогодні звідси не ходить — треба йти на Marktplatz."},{"q":"Die Frau kauft die Jacke heute.","choices":["richtig","falsch"],"answer":1,"seg":3,"trap_ru":"Цвет нравится, но «zu viel» — она ждёт распродажи.","trap_uk":"Колір подобається, але «zu viel» — вона чекає на розпродаж."},{"q":"Der Mann findet die Jacke","choices":["zu teuer.","nicht schön.","ihren Preis wert."],"answer":2,"seg":3,"trap_ru":"«Für die Qualität nicht teuer» = стоит своих денег. «Zu teuer» — мнение женщины.","trap_uk":"«Für die Qualität nicht teuer» = вартує своїх грошей. «Zu teuer» — думка жінки."}]'::jsonb,'[0,1,0,1,1,1,1,2]'::jsonb,'{"satz":"A","plays":1,"audio":true,"segments":[[{"s":"f","de":"Herr Novak, haben Sie kurz Zeit? Ich ziehe am Wochenende aus und brauche noch jemanden, der am Samstag die Schlüssel vom Hausmeister annimmt."},{"s":"m","de":"Am Samstag bin ich leider bei meiner Schwester in Köln. Aber meine Frau ist zu Hause, die macht das bestimmt."},{"s":"f","de":"Oh, super, vielen Dank! Ich bringe Ihnen dann noch ein Stück Kuchen vorbei."}],[{"s":"m","de":"Na, Olena, wie läuft''s im neuen Job?"},{"s":"f","de":"Eigentlich gut. Die Kollegen sind total nett. Nur die Schichten sind anstrengend, ich muss oft schon um sechs anfangen."},{"s":"m","de":"Und dein Chef?"},{"s":"f","de":"Der ist ganz okay. Er hat gesagt, ab Januar kann ich vielleicht in die Spätschicht wechseln."}],[{"s":"f","de":"Entschuldigung, fährt dieser Bus zum Klinikum?"},{"s":"m","de":"Nein, das ist die 12, die fährt zum Bahnhof. Zum Klinikum müssen Sie die 7 nehmen, aber die fährt heute nicht von hier, wegen der Baustelle. Gehen Sie da vorne links, zur Haltestelle Marktplatz."},{"s":"f","de":"Ach so, danke schön!"}],[{"s":"m","de":"Schau mal, die Jacke hier. Die ist doch schön, oder?"},{"s":"f","de":"Ja, die Farbe ist toll. Aber neunundachtzig Euro? Das ist mir zu viel. Ich warte lieber bis zum Schlussverkauf."},{"s":"m","de":"Wie du meinst. Ich finde, für die Qualität ist das nicht teuer."}]]}'::jsonb,null),
('h-a-4','hoeren',4,'zuordnung','B1','medien','{"de":"Sie hören Aussagen zum Thema „Kinder und Handy“. Welcher Satz (a–f) passt zu welcher Aussage?","ru":"Высказывания на тему «Дети и смартфон». Какое предложение (a–f) подходит к какому высказыванию?","uk":"Висловлювання на тему «Діти й смартфон». Яке речення (a–f) підходить до якого висловлювання?"}'::jsonb,null,null,'[{"q":"Aussage 1","choices":["a","b","c","d","e","f"],"answer":0,"seg":0,"trap_ru":"Ключ: «anrufen kann und sie mich» = родители могут связаться. Про «einfaches Handy» — не про цену.","trap_uk":"Ключ: «anrufen kann und sie mich» = батьки можуть зв''язатися. Про «einfaches Handy» — не про ціну."},{"q":"Aussage 2","choices":["a","b","c","d","e","f"],"answer":2,"seg":1,"trap_ru":"«Bei uns selbst anfangen» = быть примером. Слово «Vorbild» не звучит.","trap_uk":"«Bei uns selbst anfangen» = бути прикладом. Слово «Vorbild» не звучить."},{"q":"Aussage 3","choices":["a","b","c","d","e","f"],"answer":1,"seg":2,"trap_ru":"«Denken an nichts anderes mehr» = не могут сосредоточиться.","trap_uk":"«Denken an nichts anderes mehr» = не можуть зосередитися."}]'::jsonb,'[0,2,1]'::jsonb,'{"satz":"A","plays":2,"audio":true,"statements":["Kinder brauchen ein Handy, damit die Eltern sie erreichen können.","Handys machen Kinder unkonzentriert in der Schule.","Die Eltern sollten selbst ein Vorbild sein.","Kinder sollten erst mit vierzehn ein Handy bekommen.","Mit dem Handy lernen Kinder auch viel.","Handys sind für Kinder zu teuer."],"segments":[[{"s":"f","de":"Meine Tochter ist zehn und fährt allein mit dem Bus zum Training. Ich bin einfach ruhiger, wenn ich sie anrufen kann und sie mich. Deshalb hat sie ein Handy, aber ein ganz einfaches."}],[{"s":"m","de":"Ehrlich gesagt: Wir Erwachsenen schauen doch ständig aufs Handy, beim Essen, im Park, überall. Wie sollen die Kinder es dann anders machen? Da müssen wir zuerst bei uns selbst anfangen."}],[{"s":"f","de":"Ich bin Lehrerin, und ich sehe es jeden Tag: Wenn das Handy in der Tasche vibriert, denken die Kinder an nichts anderes mehr. Seit wir die Handys morgens einsammeln, ist es im Unterricht viel ruhiger."}]]}'::jsonb,null),
('h-b-1','hoeren',1,'mc','A2',null,'{"de":"Sie hören vier Ansagen. Zu jeder Ansage gibt es eine Aufgabe. Welche Lösung (a, b oder c) passt am besten?","ru":"Четыре объявления, к каждому одно задание.","uk":"Чотири оголошення, до кожного одне завдання."}'::jsonb,null,null,'[{"q":"Was ist heute anders?","choices":["Der Zug fährt später.","Der Zug fährt von einem anderen Gleis.","Der Zug fällt aus."],"answer":1,"seg":0,"trap_ru":"Время звучит, но «bleibt unverändert» = не меняется.","trap_uk":"Час звучить, але «bleibt unverändert» = не змінюється."},{"q":"Was soll die Mutter machen?","choices":["Katja von der Schule abholen.","Lena abholen.","Um sechs zu Hause sein."],"answer":1,"seg":1,"trap_ru":"В шесть будет дома Катя, а маму просят забрать Лену.","trap_uk":"О шостій удома буде Катя, а маму просять забрати Лену."},{"q":"Was sagt das Autohaus?","choices":["Die Reparatur kostet mehr.","Das Auto ist noch nicht fertig.","Man kann das Auto morgen abholen."],"answer":0,"seg":2,"trap_ru":"«Etwas teurer als besprochen» = дороже, чем договаривались.","trap_uk":"«Etwas teurer als besprochen» = дорожче, ніж домовлялися."},{"q":"Wann hat die Bibliothek ab nächster Woche länger geöffnet?","choices":["Am Samstag.","Am Donnerstag.","Jeden Tag bis 20 Uhr."],"answer":1,"seg":3,"trap_ru":"Суббота упомянута, но как выходной.","trap_uk":"Субота згадана, але як вихідний."}]'::jsonb,'[1,1,0,1]'::jsonb,'{"satz":"B","plays":2,"audio":true,"segments":[[{"s":"n","de":"Sehr geehrte Fahrgäste, der Regionalexpress nach Dortmund fährt heute nicht von Gleis drei, sondern von Gleis fünf ab. Die Abfahrtszeit bleibt unverändert: neun Uhr zwölf."}],[{"s":"f","de":"Hallo Mama, ich bin''s, Katja. Ich komme heute später, wir haben nach der Schule noch Theaterprobe. Kannst du Lena um vier vom Kindergarten abholen? Ich bin dann um sechs zu Hause."}],[{"s":"m","de":"Guten Tag, hier ist das Autohaus Krämer. Ihr Wagen ist fertig. Leider mussten wir auch die Bremsen erneuern, deshalb wird es etwas teurer als besprochen. Sie können das Auto heute bis neunzehn Uhr abholen."}],[{"s":"f","de":"Herzlich willkommen in der Stadtbibliothek. Bitte beachten Sie: Ab nächster Woche haben wir samstags geschlossen. Dafür sind wir donnerstags bis zwanzig Uhr für Sie da."}]]}'::jsonb,null),
('h-b-2','hoeren',2,'mc','A2','medien','{"de":"Sie hören fünf Ansagen aus dem Radio. Welche Lösung (a, b oder c) passt am besten?","ru":"Пять объявлений по радио.","uk":"П''ять оголошень по радіо."}'::jsonb,null,null,'[{"q":"Wie kommt man von Hamm nach Unna?","choices":["Mit dem Zug.","Mit dem Bus.","Gar nicht."],"answer":1,"seg":0,"trap_ru":"«Busse als Ersatz» = вместо поезда автобусы.","trap_uk":"«Busse als Ersatz» = замість поїзда автобуси."},{"q":"Was ändert sich im September?","choices":["Das Kita-Essen wird billiger.","Das Kita-Essen ist für alle kostenlos.","Die Kitas bekommen eine neue Küche."],"answer":0,"seg":1,"trap_ru":"Бесплатно только семьям с малым доходом, для остальных 2 € — дешевле.","trap_uk":"Безкоштовно лише родинам із малим доходом, для інших 2 € — дешевше."},{"q":"Was kann man heute Abend machen?","choices":["Zum Arzt gehen.","Fragen zur Gesundheit stellen.","Ein Medikament gewinnen."],"answer":1,"seg":2,"trap_ru":"Врача можно спросить по телефону, а не пойти к нему.","trap_uk":"Лікарку можна запитати телефоном, а не піти до неї."},{"q":"Am Sonntag","choices":["sind die Geschäfte den ganzen Tag offen.","fahren mehr Busse und Bahnen.","ist die Innenstadt für Autos gesperrt."],"answer":1,"seg":3,"trap_ru":"Магазины открыты только с 13 до 18, не весь день. «Häufiger» = чаще = больше.","trap_uk":"Магазини відкриті лише з 13 до 18, не весь день. «Häufiger» = частіше = більше."},{"q":"Was sollen Autofahrer morgen beachten?","choices":["Es regnet stark.","Die Straßen können glatt sein.","Es gibt viele Staus."],"answer":1,"seg":4,"trap_ru":"«Trocken» = без дождя. Glätte = гололёд.","trap_uk":"«Trocken» = без дощу. Glätte = ожеледиця."}]'::jsonb,'[1,0,1,1,1]'::jsonb,'{"satz":"B","plays":1,"audio":true,"segments":[[{"s":"m","de":"Verkehrsmeldung: Wegen eines Unfalls ist die Bahnstrecke zwischen Hamm und Unna bis voraussichtlich vierzehn Uhr gesperrt. Zwischen den beiden Bahnhöfen fahren Busse als Ersatz."}],[{"s":"n","de":"Gute Nachricht für alle Eltern: Ab September kostet das Mittagessen in den städtischen Kitas nur noch zwei Euro pro Tag. Familien mit wenig Geld zahlen gar nichts."}],[{"s":"f","de":"Heute Abend bei uns im Studio: Ärztin Dr. Meyer beantwortet Ihre Fragen zum Thema Erkältung. Rufen Sie an zwischen zwanzig und einundzwanzig Uhr unter null acht null null, zwölf, zwölf, zwölf."}],[{"s":"m","de":"Am Wochenende ist verkaufsoffener Sonntag in der Innenstadt. Die Geschäfte haben von dreizehn bis achtzehn Uhr geöffnet. Busse und Bahnen fahren an diesem Tag häufiger."}],[{"s":"n","de":"Das Wetter: Heute bleibt es trocken, aber es wird kalt, nachts bis minus fünf Grad. Autofahrer sollten morgen früh mit Glätte rechnen."}]]}'::jsonb,null),
('h-b-3','hoeren',3,'rf-mc','B1',null,'{"de":"Sie hören vier Gespräche. Zu jedem Gespräch gibt es zwei Aufgaben.","ru":"Четыре разговора, по два задания.","uk":"Чотири розмови, по два завдання."}'::jsonb,null,null,'[{"q":"Der Mann bekommt heute einen festen Termin.","choices":["richtig","falsch"],"answer":1,"seg":0,"trap_ru":"Сегодня — только открытый приём с ожиданием, фиксированный термин — завтра.","trap_uk":"Сьогодні — лише відкритий прийом з очікуванням, фіксований термін — завтра."},{"q":"Der Mann","choices":["kommt morgen um 8:30.","geht heute in die offene Sprechstunde.","sucht eine andere Praxis."],"answer":1,"seg":0,"trap_ru":"«Lieber heute Nachmittag» = выбирает сегодня после обеда.","trap_uk":"«Lieber heute Nachmittag» = обирає сьогодні по обіді."},{"q":"Igor geht am Freitag mit ins Kino.","choices":["richtig","falsch"],"answer":1,"seg":1,"trap_ru":"В пятницу он работает до десяти.","trap_uk":"У п''ятницю він працює до десятої."},{"q":"Die Kursgruppe","choices":["geht am Samstag ins Kino.","geht ohne Igor ins Kino.","geht nicht ins Kino."],"answer":1,"seg":1,"trap_ru":"Остальные могут только в пятницу — пойдут без Игоря.","trap_uk":"Інші можуть лише в п''ятницю — підуть без Ігоря."},{"q":"Der Mann versichert das Paket.","choices":["richtig","falsch"],"answer":1,"seg":2,"trap_ru":"«Nein danke» — страховка не нужна.","trap_uk":"«Nein danke» — страховка не потрібна."},{"q":"Der Mann bezahlt","choices":["bar.","mit Karte.","19,90 Euro."],"answer":1,"seg":2,"trap_ru":"Цена 19,99, а не 19,90 — ловушка с числами.","trap_uk":"Ціна 19,99, а не 19,90 — пастка з числами."},{"q":"Der Sohn ist in Mathe besser geworden.","choices":["richtig","falsch"],"answer":0,"seg":3,"trap_ru":"«Große Fortschritte» = стал лучше.","trap_uk":"«Große Fortschritte» = став кращим."},{"q":"Die Lehrerin empfiehlt","choices":["mehr Mathe zu üben.","eine Hausaufgabenhilfe.","jeden Abend ins Heft zu schauen."],"answer":1,"seg":3,"trap_ru":"Смотреть в тетрадь — это делают родители сами. Учительница советует Hausaufgabenhilfe.","trap_uk":"Дивитися в зошит — це роблять батьки самі. Учителька радить Hausaufgabenhilfe."}]'::jsonb,'[1,1,1,1,1,1,0,1]'::jsonb,'{"satz":"B","plays":1,"audio":true,"segments":[[{"s":"m","de":"Guten Morgen, ich habe Rückenschmerzen und hätte gern so schnell wie möglich einen Termin."},{"s":"f","de":"Heute ist alles voll, tut mir leid. Morgen um acht Uhr dreißig wäre etwas frei. Oder Sie kommen heute in die offene Sprechstunde ab sechzehn Uhr, aber da müssen Sie mit Wartezeit rechnen."},{"s":"m","de":"Dann komme ich lieber heute Nachmittag."}],[{"s":"f","de":"Igor, hast du am Freitag schon was vor? Wir wollen mit dem Kurs ins Kino."},{"s":"m","de":"Freitag arbeite ich bis zehn, leider. Aber am Samstag hätte ich Zeit."},{"s":"f","de":"Hm, die anderen können nur Freitag. Schade! Dann machen wir nächstes Mal zusammen was."}],[{"s":"m","de":"Ich möchte bitte dieses Paket nach Polen schicken."},{"s":"f","de":"Gern. Das wiegt sechs Kilo, das kostet neunzehn neunundneunzig. Möchten Sie es versichern?"},{"s":"m","de":"Nein danke, da sind nur Kleider drin. Aber kann ich mit Karte zahlen?"},{"s":"f","de":"Natürlich."}],[{"s":"f","de":"Frau Lehmann, Ihr Sohn hat in Mathe große Fortschritte gemacht. Aber er vergisst oft seine Hausaufgaben."},{"s":"m","de":"Ja, das weiß ich. Wir schauen jetzt jeden Abend zusammen ins Heft."},{"s":"f","de":"Sehr gut. Und vielleicht kann er auch in die Hausaufgabenhilfe am Mittwoch gehen."}]]}'::jsonb,null),
('h-b-4','hoeren',4,'zuordnung','B1','arbeit','{"de":"Sie hören Aussagen zum Thema „Homeoffice“. Welcher Satz (a–f) passt?","ru":"Высказывания на тему «Работа из дома». Какое предложение подходит?","uk":"Висловлювання на тему «Робота з дому». Яке речення підходить?"}'::jsonb,null,null,'[{"q":"Aussage 1","choices":["a","b","c","d","e","f"],"answer":1,"seg":0,"trap_ru":"Две часа в поезде → теперь время для семьи = экономия времени на дорогу.","trap_uk":"Дві години в поїзді → тепер час для родини = економія часу на дорогу."},{"q":"Aussage 2","choices":["a","b","c","d","e","f"],"answer":5,"seg":1,"trap_ru":"Медсестра: в её профессии это невозможно.","trap_uk":"Медсестра: у її професії це неможливо."},{"q":"Aussage 3","choices":["a","b","c","d","e","f"],"answer":2,"seg":2,"trap_ru":"«Langweilig» — не про концентрацию; ему не хватает разговоров с коллегами.","trap_uk":"«Langweilig» — не про концентрацію; йому бракує розмов із колегами."}]'::jsonb,'[1,5,2]'::jsonb,'{"satz":"B","plays":2,"audio":true,"statements":["Zu Hause kann man sich schlecht konzentrieren.","Man spart viel Zeit für den Weg.","Im Homeoffice fehlen die Kollegen.","Homeoffice ist nur für junge Leute gut.","Der Chef kontrolliert zu viel.","Homeoffice ist in vielen Berufen nicht möglich."],"segments":[[{"s":"m","de":"Früher war ich jeden Tag fast zwei Stunden im Zug. Jetzt arbeite ich drei Tage zu Hause, und die Zeit habe ich für meine Familie. Das ist für mich das Wichtigste."}],[{"s":"f","de":"Ich bin Krankenpflegerin. Homeoffice? Das klingt schön, aber die Patienten kann ich ja nicht per Video waschen. Für Leute wie mich ist das einfach kein Thema."}],[{"s":"m","de":"Am Anfang fand ich es super. Aber nach ein paar Monaten habe ich gemerkt: Mir fehlt der Kaffee in der Küche, das kurze Gespräch zwischendurch. Allein am Schreibtisch ist es auf Dauer langweilig."}]]}'::jsonb,null),
('l-a-1','lesen',1,'mc','A2','aemter','{"de":"Sie sind im Einkaufszentrum und suchen etwas. In welches Stockwerk (a, b oder c) gehen Sie?","ru":"Вы в торговом центре и что-то ищете. На какой этаж (a, b, c) вы пойдёте?","uk":"Ви в торговому центрі й щось шукаєте. На який поверх (a, b, c) ви підете?"}'::jsonb,'Einkaufszentrum „Ruhrpark“ – Wegweiser
insert into public.grammar_points (id,level_id,title_ru,title_uk,rule_ru,rule_uk,examples,quiz,error_types,sort) values
('g-v2','A1','Глагол на втором месте (V2)','Дієслово на другому місці (V2)','В главном предложении спрягаемый глагол всегда второй. Если в начале стоит время или место, подлежащее уходит за глагол: «Morgen gehe ich…», а не «Morgen ich gehe…». Типичная ошибка русскоязычных — ставить подлежащее перед глаголом, как в русском.','У головному реченні дієслово, що відмінюється, завжди друге. Якщо на початку час чи місце, підмет іде після дієслова: «Morgen gehe ich…», а не «Morgen ich gehe…». Типова помилка — ставити підмет перед дієсловом, як в українській.','[{"de":"Morgen gehe ich zum Arzt.","ru":"Завтра я иду к врачу.","uk":"Завтра я йду до лікаря."},{"de":"In Köln wohnt meine Schwester.","ru":"В Кёльне живёт моя сестра.","uk":"У Кельні живе моя сестра."},{"de":"Deshalb lerne ich jeden Tag Deutsch.","ru":"Поэтому я каждый день учу немецкий.","uk":"Тому я щодня вчу німецьку."}]'::jsonb,'[{"q":"Heute ___ ich keine Zeit.","options":["habe","ich habe","haben"],"answer":0},{"q":"Am Wochenende ___ ins Kino.","options":["wir gehen","gehen wir","gehen"],"answer":1},{"q":"Deshalb ___ zu spät.","options":["ich komme","komme ich","kommen ich"],"answer":1}]'::jsonb,array['word_order_v2']::text[],0),
('g-verb-final','A2','Глагол в конце придаточного','Дієслово в кінці підрядного','После weil, dass, wenn, ob, obwohl, als и относительных местоимений спрягаемый глагол уходит в самый конец. Модальный глагол — тоже в конец, после инфинитива: «…, weil ich arbeiten muss».','Після weil, dass, wenn, ob, obwohl, als і відносних займенників дієслово, що відмінюється, іде в самий кінець. Модальне — теж у кінець, після інфінітива: «…, weil ich arbeiten muss».','[{"de":"Ich komme nicht, weil ich krank bin.","ru":"Я не приду, потому что болею.","uk":"Я не прийду, бо хворію."},{"de":"Ich weiß, dass du morgen arbeiten musst.","ru":"Я знаю, что тебе завтра нужно работать.","uk":"Я знаю, що тобі завтра треба працювати."},{"de":"Wenn es regnet, bleiben wir zu Hause.","ru":"Если пойдёт дождь, останемся дома.","uk":"Якщо буде дощ, залишимося вдома."}]'::jsonb,'[{"q":"Ich lerne Deutsch, weil ich hier ___.","options":["arbeiten will","will arbeiten","arbeite will"],"answer":0},{"q":"Sie sagt, dass sie heute keine Zeit ___.","options":["hat","hat sie","haben"],"answer":0},{"q":"Wenn du Zeit ___, ruf mich an.","options":["hast","du hast","hast du"],"answer":0}]'::jsonb,array['verb_final']::text[],1),
('g-articles','A1','Артикли der / die / das','Артиклі der / die / das','Род в немецком часто не совпадает с русским: das Mädchen, die Sonne, der Löffel. Учи слово сразу с артиклем и мн. числом. Подсказки: -ung, -heit, -keit, -schaft, -ion → die; -chen, -lein → das; дни недели и месяцы → der.','Рід у німецькій часто не збігається з українським: das Mädchen, die Sonne, der Löffel. Вчи слово одразу з артиклем і множиною. Підказки: -ung, -heit, -keit, -schaft, -ion → die; -chen, -lein → das; дні тижня й місяці → der.','[{"de":"die Wohnung – die Wohnungen","ru":"квартира – квартиры","uk":"квартира – квартири"},{"de":"das Brötchen – die Brötchen","ru":"булочка – булочки","uk":"булочка – булочки"},{"de":"der Montag, der Mai","ru":"понедельник, май","uk":"понеділок, травень"}]'::jsonb,'[{"q":"___ Zeitung liegt auf dem Tisch.","options":["Der","Die","Das"],"answer":1},{"q":"___ Mädchen spielt im Park.","options":["Der","Die","Das"],"answer":2},{"q":"___ Termin ist am Montag.","options":["Der","Die","Das"],"answer":0}]'::jsonb,array['article_gender','plural']::text[],2),
('g-dativ-prep','A2','Предлоги с Dativ','Прийменники з Dativ','aus, bei, mit, nach, seit, von, zu — всегда Dativ: mit dem Bus, bei der Arbeit, seit einem Jahr. Слияния: zu + dem = zum, zu + der = zur, bei + dem = beim, von + dem = vom.','aus, bei, mit, nach, seit, von, zu — завжди Dativ: mit dem Bus, bei der Arbeit, seit einem Jahr. Злиття: zu + dem = zum, zu + der = zur, bei + dem = beim, von + dem = vom.','[{"de":"Ich fahre mit dem Bus zur Arbeit.","ru":"Я езжу на работу на автобусе.","uk":"Я їжджу на роботу автобусом."},{"de":"Seit einem Monat wohne ich in Essen.","ru":"Уже месяц я живу в Эссене.","uk":"Уже місяць я живу в Ессені."},{"de":"Ich komme gerade vom Arzt.","ru":"Я как раз от врача.","uk":"Я саме від лікаря."}]'::jsonb,'[{"q":"Ich wohne seit ___ Jahr hier.","options":["ein","einem","einen"],"answer":1},{"q":"Sie geht ___ Ärztin.","options":["zu die","zur","zum"],"answer":1},{"q":"Wir sprechen mit ___ Lehrer.","options":["den","dem","der"],"answer":1}]'::jsonb,array['case_dativ','preposition']::text[],3),
('g-akkusativ','A1','Akkusativ: einen, keinen, den','Akkusativ: einen, keinen, den','Прямое дополнение (кого? что?) стоит в Akkusativ. Меняется только мужской род: der → den, ein → einen, kein → keinen. Предлоги für, ohne, gegen, durch, um — всегда Akkusativ. «Es gibt» + Akkusativ.','Прямий додаток (кого? що?) стоїть в Akkusativ. Змінюється лише чоловічий рід: der → den, ein → einen, kein → keinen. Прийменники für, ohne, gegen, durch, um — завжди Akkusativ. «Es gibt» + Akkusativ.','[{"de":"Ich brauche einen Termin.","ru":"Мне нужна запись.","uk":"Мені потрібен запис."},{"de":"Hier gibt es keinen Aufzug.","ru":"Здесь нет лифта.","uk":"Тут немає ліфта."},{"de":"Das Geschenk ist für den Kollegen.","ru":"Подарок для коллеги.","uk":"Подарунок для колеги."}]'::jsonb,'[{"q":"Ich suche ___ Job.","options":["ein","einen","einem"],"answer":1},{"q":"Wir haben ___ Auto.","options":["kein","keinen","keine"],"answer":0},{"q":"Das ist für ___ Vater.","options":["mein","meinen","meinem"],"answer":1}]'::jsonb,array['case_akkusativ']::text[],4),
('g-wechsel','A2','Wo? – Dativ, Wohin? – Akkusativ','Wo? – Dativ, Wohin? – Akkusativ','in, an, auf, über, unter, vor, hinter, neben, zwischen: где? (место) → Dativ, куда? (движение) → Akkusativ. «Ich bin im Park» (wo), «Ich gehe in den Park» (wohin).','in, an, auf, über, unter, vor, hinter, neben, zwischen: де? (місце) → Dativ, куди? (рух) → Akkusativ. «Ich bin im Park» (wo), «Ich gehe in den Park» (wohin).','[{"de":"Das Buch liegt auf dem Tisch.","ru":"Книга лежит на столе.","uk":"Книжка лежить на столі."},{"de":"Ich lege das Buch auf den Tisch.","ru":"Я кладу книгу на стол.","uk":"Я кладу книжку на стіл."},{"de":"Wir fahren am Wochenende an die Ostsee.","ru":"На выходных мы едем на Балтику.","uk":"На вихідних ми їдемо на Балтику."}]'::jsonb,'[{"q":"Ich hänge das Bild an ___ Wand.","options":["der","die","dem"],"answer":1},{"q":"Die Kinder spielen in ___ Garten.","options":["den","dem","der"],"answer":1},{"q":"Er geht in ___ Küche.","options":["die","der","den"],"answer":0}]'::jsonb,array['preposition','case_dativ','case_akkusativ']::text[],5),
('g-perfekt','A2','Perfekt: haben или sein','Perfekt: haben чи sein','Прошедшее в разговоре — Perfekt: haben/sein на 2-м месте + Partizip II в конце. sein — с глаголами движения и смены состояния (gehen, fahren, kommen, aufstehen, einschlafen) и с sein/bleiben/passieren. Остальные — haben.','Минулий час у розмові — Perfekt: haben/sein на 2-му місці + Partizip II у кінці. sein — з дієсловами руху та зміни стану (gehen, fahren, kommen, aufstehen, einschlafen) і з sein/bleiben/passieren. Решта — haben.','[{"de":"Ich bin gestern nach Köln gefahren.","ru":"Вчера я ездил(а) в Кёльн.","uk":"Учора я їздив(ла) до Кельна."},{"de":"Wir haben lange gewartet.","ru":"Мы долго ждали.","uk":"Ми довго чекали."},{"de":"Was ist passiert?","ru":"Что случилось?","uk":"Що сталося?"}]'::jsonb,'[{"q":"Ich ___ um sechs aufgestanden.","options":["habe","bin","war"],"answer":1},{"q":"Sie ___ einen Brief geschrieben.","options":["hat","ist","wird"],"answer":0},{"q":"Wir sind zu Hause ___.","options":["geblieben","gebleibt","bleiben"],"answer":0}]'::jsonb,array['tense_perfekt']::text[],6),
('g-modal-praet','B1','Präteritum модальных и sein/haben','Präteritum модальних і sein/haben','В прошедшем модальные глаголы обычно в Präteritum, без Perfekt: ich konnte, musste, wollte, durfte, sollte. Так же war и hatte: «Ich war krank», а не «Ich bin krank gewesen» (можно, но звучит тяжелее).','У минулому модальні дієслова зазвичай у Präteritum, без Perfekt: ich konnte, musste, wollte, durfte, sollte. Так само war і hatte: «Ich war krank», а не «Ich bin krank gewesen» (можна, але звучить важче).','[{"de":"Ich konnte gestern nicht kommen.","ru":"Я вчера не смог(ла) прийти.","uk":"Я вчора не зміг(ла) прийти."},{"de":"Wir mussten lange warten.","ru":"Нам пришлось долго ждать.","uk":"Нам довелося довго чекати."},{"de":"Als Kind wollte ich Ärztin werden.","ru":"В детстве я хотела стать врачом.","uk":"У дитинстві я хотіла стати лікаркою."}]'::jsonb,'[{"q":"Letzte Woche ___ ich viel arbeiten.","options":["muss","musste","habe gemusst"],"answer":1},{"q":"Er ___ gestern keine Zeit.","options":["hatte","hat gehabt","hätte"],"answer":0},{"q":"Wir ___ nicht schlafen.","options":["konnten","können","gekonnt"],"answer":0}]'::jsonb,array['modal_verbs','tense_perfekt']::text[],7),
('g-konjunktiv','B1','Konjunktiv II вежливости','Konjunktiv II ввічливості','Вежливые просьбы и желания: ich hätte gern…, ich würde gern…, könnten Sie…?, wäre es möglich…? В письме formell это почти обязательно. «Ich will» звучит грубо — лучше «ich möchte» или «ich hätte gern».','Ввічливі прохання й побажання: ich hätte gern…, ich würde gern…, könnten Sie…?, wäre es möglich…? У листі formell це майже обов''язково. «Ich will» звучить грубо — краще «ich möchte» або «ich hätte gern».','[{"de":"Könnten Sie mir bitte helfen?","ru":"Не могли бы вы мне помочь?","uk":"Чи не могли б ви мені допомогти?"},{"de":"Ich hätte gern einen Termin.","ru":"Я бы хотел(а) записаться.","uk":"Я б хотів(ла) записатися."},{"de":"Wäre es möglich, den Termin zu verschieben?","ru":"Можно ли перенести встречу?","uk":"Чи можна перенести зустріч?"}]'::jsonb,'[{"q":"___ Sie mir bitte das Formular schicken?","options":["Können","Könnten","Konnten"],"answer":1},{"q":"Ich ___ gern ein Glas Wasser.","options":["hätte","hatte","habe gehabt"],"answer":0},{"q":"Es ___ schön, wenn du kommst.","options":["wäre","war","ist gewesen"],"answer":0}]'::jsonb,array['konjunktiv']::text[],8),
('g-relativ','B1','Относительные предложения','Відносні речення','Относительное местоимение = артикль слова, к которому относится (der, die, das, мн. die), а падеж — по роли внутри придаточного. Глагол в конце: «der Mann, den ich kenne», «die Frau, der ich helfe».','Відносний займенник = артикль слова, до якого він належить (der, die, das, мн. die), а відмінок — за роллю всередині підрядного. Дієслово в кінці: «der Mann, den ich kenne», «die Frau, der ich helfe».','[{"de":"Das ist die Wohnung, die wir mieten wollen.","ru":"Это квартира, которую мы хотим снять.","uk":"Це квартира, яку ми хочемо винайняти."},{"de":"Der Kollege, mit dem ich arbeite, ist nett.","ru":"Коллега, с которым я работаю, милый.","uk":"Колега, з яким я працюю, милий."},{"de":"Das Kind, das dort spielt, ist mein Sohn.","ru":"Ребёнок, который там играет, — мой сын.","uk":"Дитина, яка там грається, — мій син."}]'::jsonb,'[{"q":"Der Mann, ___ ich gestern getroffen habe, heißt Paul.","options":["der","den","dem"],"answer":1},{"q":"Die Frau, ___ dort wohnt, ist Ärztin.","options":["die","der","das"],"answer":0},{"q":"Das Auto, ___ ich fahre, ist alt.","options":["das","den","dem"],"answer":0}]'::jsonb,array['verb_final','article_gender']::text[],9),
('g-passiv','B1','Пассив в инструкциях и объявлениях','Пасив в інструкціях і оголошеннях','werden + Partizip II: «Die Miete wird überwiesen» — важно действие, а не кто его делает. Прошедшее: wurde + Partizip II. С модальным: muss … abgegeben werden. Часто в письмах ведомств и инструкциях.','werden + Partizip II: «Die Miete wird überwiesen» — важлива дія, а не хто її виконує. Минулий: wurde + Partizip II. З модальним: muss … abgegeben werden. Часто в листах установ та інструкціях.','[{"de":"Der Müll wird am Montag abgeholt.","ru":"Мусор вывозят в понедельник.","uk":"Сміття вивозять у понеділок."},{"de":"Der Antrag wurde bewilligt.","ru":"Заявление одобрено.","uk":"Заяву схвалено."},{"de":"Das Formular muss unterschrieben werden.","ru":"Бланк нужно подписать.","uk":"Бланк треба підписати."}]'::jsonb,'[{"q":"Die Wohnung ___ renoviert.","options":["wird","hat","ist"],"answer":0},{"q":"Das Paket wurde gestern ___.","options":["geliefert","liefern","liefert"],"answer":0},{"q":"Die Unterlagen müssen bis Freitag abgegeben ___.","options":["werden","wird","worden"],"answer":0}]'::jsonb,array['verb_conjugation']::text[],10),
('g-reflexiv','A2','Возвратные глаголы','Зворотні дієслова','sich + глагол: ich freue mich, du freust dich, er/sie freut sich, wir freuen uns, ihr freut euch, sie/Sie freuen sich. Не все русские «-ся» возвратны в немецком (lernen — учиться) и наоборот (sich erholen — отдыхать).','sich + дієслово: ich freue mich, du freust dich, er/sie freut sich, wir freuen uns, ihr freut euch, sie/Sie freuen sich. Не всі українські «-ся» зворотні в німецькій (lernen — вчитися) і навпаки (sich erholen — відпочивати).','[{"de":"Ich freue mich auf das Wochenende.","ru":"Я жду выходных.","uk":"Я чекаю на вихідні."},{"de":"Wir treffen uns um acht.","ru":"Встречаемся в восемь.","uk":"Зустрічаємося о восьмій."},{"de":"Hast du dich gut erholt?","ru":"Ты хорошо отдохнул(а)?","uk":"Ти добре відпочив(ла)?"}]'::jsonb,'[{"q":"Wir interessieren ___ für Musik.","options":["sich","uns","euch"],"answer":1},{"q":"Du musst ___ beeilen!","options":["dich","dir","sich"],"answer":0},{"q":"Er hat ___ beim Chef beschwert.","options":["ihn","sich","mich"],"answer":1}]'::jsonb,array['reflexive']::text[],11),
('g-verb-prep','B1','Глаголы с предлогами','Дієслова з прийменниками','Предлог учится вместе с глаголом: warten auf + Akk., denken an + Akk., sich freuen auf/über, sich kümmern um, sich interessieren für, teilnehmen an + Dat., sprechen mit + Dat. über + Akk. Вопрос о вещи: worauf? woran? — ответ darauf, daran.','Прийменник вчиться разом із дієсловом: warten auf + Akk., denken an + Akk., sich freuen auf/über, sich kümmern um, sich interessieren für, teilnehmen an + Dat., sprechen mit + Dat. über + Akk. Питання про річ: worauf? woran? — відповідь darauf, daran.','[{"de":"Ich warte auf den Bus.","ru":"Я жду автобус.","uk":"Я чекаю на автобус."},{"de":"Denk bitte an den Termin!","ru":"Не забудь про встречу!","uk":"Не забудь про зустріч!"},{"de":"Ich nehme an einem Kurs teil.","ru":"Я посещаю курс.","uk":"Я відвідую курс."}]'::jsonb,'[{"q":"Ich kümmere mich ___ die Kinder.","options":["für","um","auf"],"answer":1},{"q":"Sie freut sich ___ den Urlaub.","options":["auf","an","für"],"answer":0},{"q":"Wir sprechen ___ das Problem.","options":["von","über","um"],"answer":1}]'::jsonb,array['preposition']::text[],12),
('g-negation','A1','nicht или kein','nicht чи kein','kein — отрицает существительное с ein или без артикля: «Ich habe kein Auto», «Ich habe keine Zeit». nicht — всё остальное: глагол, прилагательное, слово с определённым артиклем: «Das Auto ist nicht neu», «Ich finde den Schlüssel nicht».','kein — заперечує іменник з ein або без артикля: «Ich habe kein Auto», «Ich habe keine Zeit». nicht — усе інше: дієслово, прикметник, слово з означеним артиклем: «Das Auto ist nicht neu», «Ich finde den Schlüssel nicht».','[{"de":"Ich habe heute keine Zeit.","ru":"У меня сегодня нет времени.","uk":"У мене сьогодні немає часу."},{"de":"Das ist nicht mein Handy.","ru":"Это не мой телефон.","uk":"Це не мій телефон."},{"de":"Er kommt heute nicht.","ru":"Он сегодня не придёт.","uk":"Він сьогодні не прийде."}]'::jsonb,'[{"q":"Ich habe ___ Hunger.","options":["nicht","keinen","kein"],"answer":1},{"q":"Das Essen ist ___ warm.","options":["nicht","kein","keine"],"answer":0},{"q":"Wir haben ___ Kinder.","options":["nicht","keine","kein"],"answer":1}]'::jsonb,array['negation']::text[],13),
('g-adj','B1','Окончания прилагательных — минимум','Закінчення прикметників — мінімум','После der/die/das почти всегда -e (ед. ч., Nom.) или -en (всё остальное): der neue Job, mit dem neuen Job. После ein сигнал рода переходит к прилагательному: ein neuer Job, ein neues Auto. Без артикля — как у der/das: guter Kaffee, frisches Brot.','Після der/die/das майже завжди -e (одн., Nom.) або -en (усе інше): der neue Job, mit dem neuen Job. Після ein сигнал роду переходить до прикметника: ein neuer Job, ein neues Auto. Без артикля — як у der/das: guter Kaffee, frisches Brot.','[{"de":"Ich suche eine günstige Wohnung.","ru":"Я ищу недорогую квартиру.","uk":"Я шукаю недорогу квартиру."},{"de":"Wir haben einen neuen Nachbarn.","ru":"У нас новый сосед.","uk":"У нас новий сусід."},{"de":"Mit freundlichen Grüßen","ru":"С уважением","uk":"З повагою"}]'::jsonb,'[{"q":"Das ist ein gut___ Angebot.","options":["es","er","en"],"answer":0},{"q":"Ich wohne in einer klein___ Wohnung.","options":["e","en","er"],"answer":1},{"q":"Der neu___ Kollege ist nett.","options":["e","en","er"],"answer":0}]'::jsonb,array['adjective_ending']::text[],14),
('g-conj','B1','Связки: deshalb, trotzdem, denn, weil','Зв''язки: deshalb, trotzdem, denn, weil','Три группы: und, aber, oder, denn, sondern — порядок не меняется. deshalb, trotzdem, dann, danach, außerdem — глагол сразу после них (V2). weil, dass, obwohl, wenn — глагол в конец. Это главный критерий «связности» на DTZ.','Три групи: und, aber, oder, denn, sondern — порядок не змінюється. deshalb, trotzdem, dann, danach, außerdem — дієслово одразу після них (V2). weil, dass, obwohl, wenn — дієслово в кінець. Це головний критерій «зв''язності» на DTZ.','[{"de":"Ich bin krank, deshalb bleibe ich zu Hause.","ru":"Я болею, поэтому остаюсь дома.","uk":"Я хворію, тому залишаюся вдома."},{"de":"Ich bin krank, denn ich habe Fieber.","ru":"Я болею, ведь у меня температура.","uk":"Я хворію, адже в мене температура."},{"de":"Obwohl ich müde bin, gehe ich zum Kurs.","ru":"Хотя я устал(а), я иду на курс.","uk":"Хоча я втомився(лася), я йду на курс."}]'::jsonb,'[{"q":"Es regnet, trotzdem ___ spazieren.","options":["wir gehen","gehen wir","wir gehen spazieren"],"answer":1},{"q":"Ich komme nicht, denn ich ___ arbeiten.","options":["muss","arbeiten muss","muss ich"],"answer":0},{"q":"Er lernt viel, weil er die Prüfung bestehen ___.","options":["will","will er","wollen"],"answer":0}]'::jsonb,array['word_order_v2','verb_final']::text[],15)
